"use client";

import { useState, useEffect } from "react";
import { useRouter } from "next/navigation";
import { createClientComponentClient } from "@supabase/auth-helpers-nextjs";

interface Category {
  id: string;
  name: string;
  slug: string;
  icon: string;
  description: string;
}

export default function PostarCoisasPage() {
  const router = useRouter();
  const supabase = createClientComponentClient();
  
  const [loading, setLoading] = useState(false);
  const [categories, setCategories] = useState<Category[]>([]);
  const [uploading, setUploading] = useState(false);
  
  // Form state
  const [formData, setFormData] = useState({
    category_id: "",
    title: "",
    description: "",
    listing_type: "sell",
    price: "",
    is_negotiable: false,
    accepts_trade: false,
    condition: "good",
    brand: "",
    model: "",
    quantity: "1",
    state: "",
    city: "",
    neighborhood: "",
    zip_code: "",
    shipping_available: false,
    shipping_cost: "",
    weight_kg: "",
    tags: "",
  });
  
  const [photos, setPhotos] = useState<string[]>([]);
  const [error, setError] = useState("");
  const [success, setSuccess] = useState("");
  const [authChecked, setAuthChecked] = useState(false);
  const [isAuthenticated, setIsAuthenticated] = useState(false);

  // Check authentication on mount
  useEffect(() => {
    void checkAuth();
  }, []);

  const checkAuth = async () => {
    const { data: { session } } = await supabase.auth.getSession();
    
    if (!session) {
      router.push("/entrar?redirect=/acheme-coisas/postar");
      return;
    }
    
    setIsAuthenticated(true);
    setAuthChecked(true);
    void fetchCategories();
  };

  // Fetch categories on mount
  useEffect(() => {
    if (isAuthenticated) {
      void fetchCategories();
    }
  }, [isAuthenticated]);

  const fetchCategories = async () => {
    const { data, error } = await supabase
      .from("categories")
      .select("*")
      .eq("is_active", true)
      .is("parent_id", null)
      .order("display_order");
    
    if (data) setCategories(data);
  };

  const handleImageUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (!e.target.files || e.target.files.length === 0) return;
    
    setUploading(true);
    setError("");
    
    try {
      const file = e.target.files[0];
      const fileExt = file.name.split(".").pop();
      const fileName = `${Math.random()}.${fileExt}`;
      const filePath = `listings/${fileName}`;

      const { data, error } = await supabase.storage
        .from("imagens-sitios")
        .upload(filePath, file);

      if (error) throw error;

      const { data: { publicUrl } } = supabase.storage
        .from("imagens-sitios")
        .getPublicUrl(filePath);

      setPhotos([...photos, publicUrl]);
      setSuccess("Foto adicionada!");
      setTimeout(() => setSuccess(""), 2000);
    } catch (err: any) {
      setError(err.message || "Erro ao fazer upload da foto");
    } finally {
      setUploading(false);
    }
  };

  const removePhoto = (index: number) => {
    setPhotos(photos.filter((_, i) => i !== index));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError("");

    try {
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) {
        router.push("/entrar?redirect=/acheme-coisas/postar");
        return;
      }

      // Generate slug from title
      const slug = formData.title
        .toLowerCase()
        .normalize("NFD")
        .replace(/[\u0300-\u036f]/g, "")
        .replace(/[^a-z0-9]+/g, "-")
        .replace(/(^-|-$)/g, "");

      // Parse tags
      const tagsArray = formData.tags
        .split(",")
        .map(tag => tag.trim())
        .filter(tag => tag.length > 0);

      const listingData = {
        user_id: user.id,
        category_id: formData.category_id,
        title: formData.title,
        description: formData.description,
        listing_type: formData.listing_type,
        price: formData.price ? parseFloat(formData.price) : null,
        is_negotiable: formData.is_negotiable,
        accepts_trade: formData.accepts_trade,
        condition: formData.condition,
        brand: formData.brand || null,
        model: formData.model || null,
        quantity: parseInt(formData.quantity),
        photos: photos,
        state: formData.state,
        city: formData.city,
        neighborhood: formData.neighborhood || null,
        zip_code: formData.zip_code || null,
        shipping_available: formData.shipping_available,
        shipping_cost: formData.shipping_cost ? parseFloat(formData.shipping_cost) : null,
        weight_kg: formData.weight_kg ? parseFloat(formData.weight_kg) : null,
        tags: tagsArray,
        slug: `${slug}-${Date.now()}`,
        status: "active",
        published_at: new Date().toISOString(),
      };

      const { data, error } = await supabase
        .from("listings")
        .insert([listingData])
        .select()
        .single();

      if (error) {
        console.error("Database error:", error);
        throw error;
      }

      setSuccess("An├║ncio publicado com sucesso! Redirecionando...");
      console.log("Listing created:", data);
      setTimeout(() => {
        router.push(`/acheme-coisas/publicado?id=${data.id}`);
      }, 1500);
    } catch (err: any) {
      console.error("Submit error:", err);
      setError(err.message || "Erro ao publicar an├║ncio");
    } finally {
      setLoading(false);
    }
  };

  // Loading state while checking auth
  if (!authChecked) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-orange-50 to-blue-50 flex items-center justify-center">
        <div className="text-center">
          <div className="animate-spin rounded-full h-16 w-16 border-b-2 border-orange-500 mx-auto mb-4"></div>
          <p className="text-gray-600">Verificando autentica├º├úo...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gradient-to-br from-orange-50 to-green-50 py-12">
      <div className="max-w-4xl mx-auto px-4">
        {/* Header */}
        <div className="text-center mb-8">
          <h1 className="text-4xl font-bold text-gray-800 mb-2">
            ­ƒøì´©Å Anunciar em AcheMeCoisas
          </h1>
          <p className="text-gray-600">
            Venda, troque ou doe qualquer coisa de forma r├ípida e f├ícil
          </p>
        </div>

        {/* Error/Success Messages */}
        {error && (
          <div className="bg-red-50 border border-red-200 text-red-700 px-4 py-3 rounded mb-6">
            {error}
          </div>
        )}
        {success && (
          <div className="bg-green-50 border border-green-200 text-green-700 px-4 py-3 rounded mb-6">
            {success}
          </div>
        )}

        {/* Form */}
        <form onSubmit={handleSubmit} className="bg-white rounded-2xl shadow-xl p-8 space-y-8">
          
          {/* Tipo de An├║ncio */}
          <div>
            <label className="block text-sm font-semibold text-gray-700 mb-3">
              Tipo de An├║ncio *
            </label>
            <div className="grid grid-cols-2 md:grid-cols-5 gap-3">
              {[
                { value: "sell", label: "Vender", icon: "­ƒÆ░" },
                { value: "buy", label: "Comprar", icon: "­ƒøÆ" },
                { value: "trade", label: "Trocar", icon: "­ƒöä" },
                { value: "free", label: "Doar", icon: "­ƒÄü" },
                { value: "wanted", label: "Procuro", icon: "­ƒöì" },
              ].map((type) => (
                <button
                  key={type.value}
                  type="button"
                  onClick={() => setFormData({ ...formData, listing_type: type.value })}
                  className={`p-4 rounded-lg border-2 transition ${
                    formData.listing_type === type.value
                      ? "border-orange-500 bg-orange-50"
                      : "border-gray-200 hover:border-gray-300"
                  }`}
                >
                  <div className="text-3xl mb-1">{type.icon}</div>
                  <div className="text-sm font-medium">{type.label}</div>
                </button>
              ))}
            </div>
          </div>

          {/* Categoria */}
          <div>
            <label className="block text-sm font-semibold text-gray-700 mb-2">
              Categoria *
            </label>
            <select
              value={formData.category_id}
              onChange={(e) => setFormData({ ...formData, category_id: e.target.value })}
              required
              className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-orange-500 focus:border-transparent"
            >
              <option value="">Selecione uma categoria</option>
              {categories.map((cat) => (
                <option key={cat.id} value={cat.id}>
                  {cat.icon} {cat.name}
                </option>
              ))}
            </select>
          </div>

          {/* T├¡tulo */}
          <div>
            <label className="block text-sm font-semibold text-gray-700 mb-2">
              T├¡tulo do An├║ncio *
            </label>
            <input
              type="text"
              value={formData.title}
              onChange={(e) => setFormData({ ...formData, title: e.target.value })}
              required
              maxLength={200}
              placeholder="Ex: iPhone 13 Pro 256GB Azul Sierra - Seminovo"
              className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-orange-500 focus:border-transparent"
            />
            <p className="text-sm text-gray-500 mt-1">
              {formData.title.length}/200 caracteres
            </p>
          </div>

          {/* Descri├º├úo */}
          <div>
            <label className="block text-sm font-semibold text-gray-700 mb-2">
              Descri├º├úo *
            </label>
            <textarea
              value={formData.description}
              onChange={(e) => setFormData({ ...formData, description: e.target.value })}
              required
              rows={6}
              placeholder="Descreva o item em detalhes: estado de conserva├º├úo, motivo da venda, acess├│rios inclusos, etc."
              className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-orange-500 focus:border-transparent"
            />
          </div>

          {/* Pre├ºo */}
          {formData.listing_type !== "free" && formData.listing_type !== "wanted" && (
            <div className="grid md:grid-cols-2 gap-6">
              <div>
                <label className="block text-sm font-semibold text-gray-700 mb-2">
                  Pre├ºo (R$) *
                </label>
                <input
                  type="number"
                  value={formData.price}
                  onChange={(e) => setFormData({ ...formData, price: e.target.value })}
                  required={formData.listing_type === "sell"}
                  step="0.01"
                  min="0"
                  placeholder="0,00"
                  className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-orange-500 focus:border-transparent"
                />
              </div>
              <div className="flex flex-col gap-3 justify-center">
                <label className="flex items-center gap-2 cursor-pointer">
                  <input
                    type="checkbox"
                    checked={formData.is_negotiable}
                    onChange={(e) => setFormData({ ...formData, is_negotiable: e.target.checked })}
                    className="w-5 h-5 text-orange-500 rounded focus:ring-orange-500"
                  />
                  <span className="text-sm font-medium text-gray-700">­ƒÆ¼ Pre├ºo negoci├ível</span>
                </label>
                <label className="flex items-center gap-2 cursor-pointer">
                  <input
                    type="checkbox"
                    checked={formData.accepts_trade}
                    onChange={(e) => setFormData({ ...formData, accepts_trade: e.target.checked })}
                    className="w-5 h-5 text-orange-500 rounded focus:ring-orange-500"
                  />
                  <span className="text-sm font-medium text-gray-700">­ƒöä Aceito trocas</span>
                </label>
              </div>
            </div>
          )}

          {/* Condi├º├úo e Detalhes */}
          <div className="grid md:grid-cols-3 gap-6">
            <div>
              <label className="block text-sm font-semibold text-gray-700 mb-2">
                Condi├º├úo
              </label>
              <select
                value={formData.condition}
                onChange={(e) => setFormData({ ...formData, condition: e.target.value })}
                className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-orange-500 focus:border-transparent"
              >
                <option value="new">Novo</option>
                <option value="like_new">Seminovo</option>
                <option value="good">Bom estado</option>
                <option value="fair">Estado regular</option>
                <option value="for_parts">Para pe├ºas</option>
              </select>
            </div>
            <div>
              <label className="block text-sm font-semibold text-gray-700 mb-2">
                Marca
              </label>
              <input
                type="text"
                value={formData.brand}
                onChange={(e) => setFormData({ ...formData, brand: e.target.value })}
                placeholder="Ex: Apple, Samsung, Nike..."
                className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-orange-500 focus:border-transparent"
              />
            </div>
            <div>
              <label className="block text-sm font-semibold text-gray-700 mb-2">
                Modelo
              </label>
              <input
                type="text"
                value={formData.model}
                onChange={(e) => setFormData({ ...formData, model: e.target.value })}
                placeholder="Ex: iPhone 13 Pro"
                className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-orange-500 focus:border-transparent"
              />
            </div>
          </div>

          {/* Fotos */}
          <div>
            <label className="block text-sm font-semibold text-gray-700 mb-2">
              Fotos do Produto
            </label>
            <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mb-4">
              {photos.map((photo, index) => (
                <div key={index} className="relative group">
                  <img
                    src={photo}
                    alt={`Foto ${index + 1}`}
                    className="w-full h-32 object-cover rounded-lg"
                  />
                  <button
                    type="button"
                    onClick={() => removePhoto(index)}
                    className="absolute top-2 right-2 bg-red-500 text-white p-2 rounded-full opacity-0 group-hover:opacity-100 transition"
                  >
                    Ô£ò
                  </button>
                </div>
              ))}
              {photos.length < 8 && (
                <label className="w-full h-32 border-2 border-dashed border-gray-300 rounded-lg flex flex-col items-center justify-center cursor-pointer hover:border-orange-500 transition">
                  <input
                    type="file"
                    accept="image/*"
                    onChange={handleImageUpload}
                    disabled={uploading}
                    className="hidden"
                  />
                  <span className="text-3xl mb-1">­ƒôÀ</span>
                  <span className="text-sm text-gray-600">
                    {uploading ? "Enviando..." : "Adicionar foto"}
                  </span>
                </label>
              )}
            </div>
            <p className="text-sm text-gray-500">
              {photos.length}/8 fotos ÔÇó Primeira foto ser├í a capa do an├║ncio
            </p>
          </div>

          {/* Localiza├º├úo */}
          <div>
            <h3 className="text-lg font-semibold text-gray-800 mb-4">­ƒôì Localiza├º├úo</h3>
            <div className="grid md:grid-cols-2 gap-6">
              <div>
                <label className="block text-sm font-semibold text-gray-700 mb-2">
                  Estado *
                </label>
                <input
                  type="text"
                  value={formData.state}
                  onChange={(e) => setFormData({ ...formData, state: e.target.value })}
                  required
                  placeholder="Ex: DF, SP, RJ..."
                  maxLength={2}
                  className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-orange-500 focus:border-transparent uppercase"
                />
              </div>
              <div>
                <label className="block text-sm font-semibold text-gray-700 mb-2">
                  Cidade *
                </label>
                <input
                  type="text"
                  value={formData.city}
                  onChange={(e) => setFormData({ ...formData, city: e.target.value })}
                  required
                  placeholder="Ex: Bras├¡lia, S├úo Paulo..."
                  className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-orange-500 focus:border-transparent"
                />
              </div>
              <div>
                <label className="block text-sm font-semibold text-gray-700 mb-2">
                  Bairro
                </label>
                <input
                  type="text"
                  value={formData.neighborhood}
                  onChange={(e) => setFormData({ ...formData, neighborhood: e.target.value })}
                  placeholder="Ex: Asa Sul, Vila Mariana..."
                  className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-orange-500 focus:border-transparent"
                />
              </div>
              <div>
                <label className="block text-sm font-semibold text-gray-700 mb-2">
                  CEP
                </label>
                <input
                  type="text"
                  value={formData.zip_code}
                  onChange={(e) => setFormData({ ...formData, zip_code: e.target.value })}
                  placeholder="00000-000"
                  maxLength={9}
                  className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-orange-500 focus:border-transparent"
                />
              </div>
            </div>
          </div>

          {/* Entrega */}
          <div>
            <h3 className="text-lg font-semibold text-gray-800 mb-4">­ƒôª Op├º├Áes de Entrega</h3>
            <label className="flex items-center gap-2 cursor-pointer mb-4">
              <input
                type="checkbox"
                checked={formData.shipping_available}
                onChange={(e) => setFormData({ ...formData, shipping_available: e.target.checked })}
                className="w-5 h-5 text-orange-500 rounded focus:ring-orange-500"
              />
              <span className="text-sm font-medium text-gray-700">
                ­ƒô« Envio dispon├¡vel para todo Brasil
              </span>
            </label>
            
            {formData.shipping_available && (
              <div className="grid md:grid-cols-3 gap-6 pl-7">
                <div>
                  <label className="block text-sm font-semibold text-gray-700 mb-2">
                    Custo de envio (R$)
                  </label>
                  <input
                    type="number"
                    value={formData.shipping_cost}
                    onChange={(e) => setFormData({ ...formData, shipping_cost: e.target.value })}
                    step="0.01"
                    placeholder="0,00"
                    className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-orange-500 focus:border-transparent"
                  />
                  <p className="text-xs text-gray-500 mt-1">Deixe vazio para calcular depois</p>
                </div>
                <div>
                  <label className="block text-sm font-semibold text-gray-700 mb-2">
                    Peso (kg)
                  </label>
                  <input
                    type="number"
                    value={formData.weight_kg}
                    onChange={(e) => setFormData({ ...formData, weight_kg: e.target.value })}
                    step="0.01"
                    placeholder="0,00"
                    className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-orange-500 focus:border-transparent"
                  />
                </div>
              </div>
            )}
          </div>

          {/* Tags */}
          <div>
            <label className="block text-sm font-semibold text-gray-700 mb-2">
              Tags (palavras-chave)
            </label>
            <input
              type="text"
              value={formData.tags}
              onChange={(e) => setFormData({ ...formData, tags: e.target.value })}
              placeholder="Ex: gamer, RGB, mec├ónico (separadas por v├¡rgula)"
              className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-orange-500 focus:border-transparent"
            />
            <p className="text-sm text-gray-500 mt-1">
              Ajuda compradores a encontrar seu an├║ncio
            </p>
          </div>

          {/* Submit Button */}
          <div className="flex gap-4">
            <button
              type="button"
              onClick={() => router.back()}
              className="flex-1 px-8 py-4 bg-gray-200 text-gray-700 rounded-lg font-semibold hover:bg-gray-300 transition"
            >
              Cancelar
            </button>
            <button
              type="submit"
              disabled={loading}
              className="flex-1 px-8 py-4 bg-gradient-to-r from-orange-500 to-orange-600 text-white rounded-lg font-semibold hover:from-orange-600 hover:to-orange-700 disabled:opacity-50 transition shadow-lg"
            >
              {loading ? "Publicando..." : "­ƒÜÇ Publicar An├║ncio"}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
}

"use client";

import { useEffect, useState, Suspense } from "react";
import { useRouter, useSearchParams } from "next/navigation";
import { createClientComponentClient } from "@supabase/auth-helpers-nextjs";
import Link from "next/link";

function AnuncioPublicadoContent() {
  const router = useRouter();
  const searchParams = useSearchParams();
  const supabase = createClientComponentClient();
  
  const listingId = searchParams.get("id");
  const [listing, setListing] = useState<any>(null);
  const [loading, setLoading] = useState(true);
  const [processing, setProcessing] = useState(false);

  useEffect(() => {
    if (listingId) {
      void fetchListing();
    }
  }, [listingId]);

  const fetchListing = async () => {
    const { data, error } = await supabase
      .from("listings")
      .select(`
        *,
        categories (name, icon)
      `)
      .eq("id", listingId)
      .single();

    if (data) setListing(data);
    setLoading(false);
  };

  const handleUpgrade = async (plan: "destaque" | "marketing") => {
    if (!listingId) return;
    
    setProcessing(true);
    
    try {
      // Obter token de autentica├º├úo
      const { data: { session } } = await supabase.auth.getSession();
      
      if (!session) {
        alert("Voc├¬ precisa estar logado para fazer upgrade");
        router.push("/entrar");
        return;
      }

      // Chamar API para criar sess├úo de checkout
      const response = await fetch("/api/checkout/create-session", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          "Authorization": `Bearer ${session.access_token}`,
        },
        body: JSON.stringify({
          listingId,
          productType: plan,
        }),
      });

      const data = await response.json();

      if (!response.ok) {
        throw new Error(data.error || "Erro ao criar sess├úo de pagamento");
      }

      // Redirecionar para checkout do Stripe
      window.location.href = data.url;
    } catch (error: any) {
      console.error("Erro ao processar pagamento:", error);
      alert(`Erro ao processar pagamento: ${error.message}`);
      setProcessing(false);
    }
  };

  if (loading) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-green-50 to-blue-50 flex items-center justify-center">
        <div className="text-center">
          <div className="animate-spin rounded-full h-16 w-16 border-b-2 border-orange-500 mx-auto mb-4"></div>
          <p className="text-gray-600">Carregando...</p>
        </div>
      </div>
    );
  }

  if (!listing) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-red-50 to-orange-50 flex items-center justify-center p-4">
        <div className="bg-white rounded-2xl shadow-xl p-8 max-w-md text-center">
          <div className="text-6xl mb-4">ÔØî</div>
          <h1 className="text-2xl font-bold text-gray-800 mb-2">An├║ncio n├úo encontrado</h1>
          <p className="text-gray-600 mb-6">O an├║ncio que voc├¬ procura n├úo existe.</p>
          <Link 
            href="/"
