// Action Confirmation Modal
function ActionModal({
  action,
  verification,
  notes,
  setNotes,
  rejectionReason,
  setRejectionReason,
  loading,
  onConfirm,
  onCancel,
}: {
  action: 'approve' | 'reject';
  verification: Verification;
  notes: string;
  setNotes: (notes: string) => void;
  rejectionReason: string;
  setRejectionReason: (reason: string) => void;
  loading: boolean;
  onConfirm: () => void;
  onCancel: () => void;
}) {
  const isApprove = action === 'approve';

  return (
    <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
      <div className="bg-white rounded-lg max-w-md w-full p-6">
        <h3 className="text-xl font-bold text-gray-900 mb-4">
          {isApprove ? 'Aprovar Verifica├º├úo' : 'Rejeitar Verifica├º├úo'}
        </h3>

        <p className="text-gray-600 mb-4">
          Confirma a {isApprove ? 'aprova├º├úo' : 'rejei├º├úo'} da verifica├º├úo de{' '}
          <span className="font-medium">{verification.full_name}</span>?
        </p>

        {!isApprove && (
          <div className="mb-4">
            <label className="block text-sm font-medium text-gray-700 mb-2">
              Motivo da Rejei├º├úo *
            </label>
            <select
              value={rejectionReason}
              onChange={(e) => setRejectionReason(e.target.value)}
              className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-red-500 focus:border-transparent"
              required
            >
              <option value="">Selecione um motivo</option>
              <option value="Documento ileg├¡vel ou de m├í qualidade">Documento ileg├¡vel ou de m├í qualidade</option>
              <option value="Selfie n├úo mostra rosto claramente">Selfie n├úo mostra rosto claramente</option>
              <option value="Documento fora da validade">Documento fora da validade</option>
              <option value="Dados n├úo conferem">Dados n├úo conferem</option>
              <option value="Documento adulterado ou suspeito">Documento adulterado ou suspeito</option>
              <option value="Outros">Outros</option>
            </select>
          </div>
        )}

        <div className="mb-6">
          <label className="block text-sm font-medium text-gray-700 mb-2">
            Notas Internas (opcional)
          </label>
          <textarea
            value={notes}
            onChange={(e) => setNotes(e.target.value)}
            rows={3}
            className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
            placeholder="Adicione observa├º├Áes para refer├¬ncia futura..."
          />
        </div>

        <div className="flex gap-4">
          <button
            onClick={onCancel}
            disabled={loading}
            className="flex-1 bg-gray-200 text-gray-700 py-2 px-4 rounded-lg font-medium hover:bg-gray-300 focus:outline-none focus:ring-2 focus:ring-gray-500 focus:ring-offset-2 disabled:opacity-50 transition-colors"
          >
            Cancelar
          </button>
          <button
            onClick={onConfirm}
            disabled={loading || (!isApprove && !rejectionReason)}
            className={`flex-1 ${
              isApprove ? 'bg-green-600 hover:bg-green-700' : 'bg-red-600 hover:bg-red-700'
            } text-white py-2 px-4 rounded-lg font-medium focus:outline-none focus:ring-2 focus:ring-offset-2 disabled:opacity-50 disabled:cursor-not-allowed transition-colors`}
          >
            {loading ? 'Processando...' : isApprove ? 'Confirmar Aprova├º├úo' : 'Confirmar Rejei├º├úo'}
          </button>
        </div>
      </div>
    </div>
  );
}

"use client";
import { useEffect, useState } from "react";
import { useI18n } from "@/lib/i18n";

interface PendingVerification {
  id: string;
  full_name: string;
  email: string;
  cpf: string;
  birth_date?: string;
  created_at: string;
  verification_status: string;
  rejection_reason?: string;
  police_alert?: boolean;
}

export default function AdminVerificationsPage() {
  const { t } = useI18n();
  const [verifications, setVerifications] = useState<PendingVerification[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetch("/api/admin/pending-verifications")
      .then((res) => res.json())
      .then((data) => {
        setVerifications(data.verifications || []);
        setLoading(false);
      })
      .catch((e) => {
        setError(e.message);
        setLoading(false);
      });
  }, []);

  // Admin action handlers
  const handleAction = async (id: string, action: 'approve' | 'reject') => {
    setLoading(true);
    setError(null);
    try {
      const res = await fetch(`/api/admin/pending-verifications`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ id, action }),
      });
      if (!res.ok) throw new Error(await res.text());
      // Refresh list
      const data = await res.json();
      setVerifications(data.verifications || []);
    } catch (e: any) {
      setError(e.message);
    }
    setLoading(false);
  };

  return (
    <div className="max-w-5xl mx-auto p-8">
      <h1 className="text-3xl font-bold mb-6 text-[#D4AF37]">
        {t("admin.verifications_title") || "Pending Verifications"}
      </h1>
      {loading && <div>{t("admin.loading") || "Loading..."}</div>}
      {error && <div className="text-red-500">{error}</div>}
      <table className="w-full border border-[#242424] rounded-xl overflow-hidden">
        <thead className="bg-[#181818] text-[#D4AF37]">
          <tr>
            <th className="p-3">{t("admin.name") || "Name"}</th>
            <th className="p-3">{t("admin.email") || "Email"}</th>
            <th className="p-3">{t("admin.cpf") || "CPF"}</th>
            <th className="p-3">{t("admin.birth_date") || "Birth Date"}</th>
            <th className="p-3">{t("admin.status") || "Status"}</th>
            <th className="p-3">{t("admin.actions") || "Actions"}</th>
            <th className="p-3">Alert</th>
          </tr>
        </thead>
        <tbody>
          {verifications.map((v) => (
            <tr key={v.id} className="border-b border-[#242424]">
              <td className="p-3">{v.full_name}</td>
              <td className="p-3">{v.email}</td>
              <td className="p-3">{v.cpf}</td>
              <td className="p-3">{v.birth_date || "-"}</td>
              <td className="p-3">{t(`admin.status_${v.verification_status}`) || v.verification_status}</td>
              <td className="p-3">
                {v.verification_status === 'needs_review' && (
                  <>
                    <button
                      className="px-3 py-1 bg-[#8B9B6E] text-white rounded mr-2 hover:bg-[#6b7b4e]"
                      onClick={() => handleAction(v.id, 'approve')}
                    >
                      {t("admin.approve") || "Approve"}
                    </button>
                    <button
                      className="px-3 py-1 bg-[#CD5C5C] text-white rounded hover:bg-[#a94442]"
                      onClick={() => handleAction(v.id, 'reject')}
                    >
                      {t("admin.reject") || "Reject"}
                    </button>
                  </>
                )}
              </td>
              <td className="p-3">
                {v.police_alert ? (
                  <span className="text-red-500 font-bold">­ƒÜ¿</span>
                ) : null}
              </td>
            </tr>
          ))}
        </tbody>
      </table>
      {verifications.length === 0 && !loading && (
        <div className="mt-8 text-[#A8896B]">{t("admin.no_pending") || "No pending verifications."}</div>
      )}
    </div>
  );
}

