import { NextResponse } from "next/server";
import { getStripe, STRIPE_PRICES } from "@/lib/stripe";
import { createClient } from "@supabase/supabase-js";

export async function POST(req: Request) {
  try {
    const { listingId, productType } = await req.json();

    if (!listingId || !productType) {
      return NextResponse.json(
        { error: "Listing ID e tipo de produto s├úo obrigat├│rios" },
        { status: 400 }
      );
    }

    // Pegar token de autentica├º├úo do header
    const authHeader = req.headers.get("authorization");
    const token = authHeader?.replace("Bearer ", "");

    if (!token) {
      return NextResponse.json(
        { error: "Token de autentica├º├úo ausente" },
        { status: 401 }
      );
    }

    // Criar cliente Supabase com o token do usu├írio
    const supabase = createClient(
      process.env.NEXT_PUBLIC_SUPABASE_URL!,
      process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!,
      {
        global: {
          headers: {
            Authorization: `Bearer ${token}`,
          },
        },
      }
    );

    // Verificar autentica├º├úo
    const {
      data: { user },
      error: authError,
    } = await supabase.auth.getUser();

    if (authError || !user) {
      return NextResponse.json(
        { error: "Usu├írio n├úo autenticado" },
        { status: 401 }
      );
    }

    // ============================================
    // VERIFICA├ç├âO DE IDENTIDADE OBRIGAT├ôRIA
    // ============================================
    // Check if user is verified before allowing premium purchases
    const { data: profile, error: profileError } = await supabase
      .from("user_profiles")
      .select("verification_status")
      .eq("user_id", user.id)
      .single();

    if (profileError) {
      console.error("Error fetching user profile:", profileError);
      return NextResponse.json(
        { error: "Erro ao verificar perfil do usu├írio" },
        { status: 500 }
      );
    }

    // Require verification for premium features
    if (profile?.verification_status !== "approved") {
      return NextResponse.json(
        { 
          error: "Verifica├º├úo de identidade necess├íria",
          requiresVerification: true,
          verificationStatus: profile?.verification_status || "not_started"
        },
        { status: 403 }
      );
    }

    // Verificar se o listing existe e pertence ao usu├írio
    const { data: listing, error: listingError } = await supabase
      .from("listings")
      .select("id, title, user_id")
      .eq("id", listingId)
      .single();

    if (listingError || !listing) {
      return NextResponse.json(
        { error: "An├║ncio n├úo encontrado" },
        { status: 404 }
      );
    }

    if (listing.user_id !== user.id) {
      return NextResponse.json(
        { error: "Voc├¬ n├úo tem permiss├úo para modificar este an├║ncio" },
        { status: 403 }
      );
    }

    // Selecionar o pre├ºo correto
    const priceId =
      productType === "destaque"
        ? STRIPE_PRICES.DESTAQUE
        : STRIPE_PRICES.MARKETING;

    if (!priceId) {
      return NextResponse.json(
        { error: "Price ID n├úo configurado" },
        { status: 500 }
      );
    }

    // Criar sess├úo de checkout do Stripe
    const stripe = getStripe();
    const session = await stripe.checkout.sessions.create({
      payment_method_types: ["card"], // Pix ser├í adicionado depois
      line_items: [
        {
          price: priceId,
          quantity: 1,
        },
      ],
      mode: "payment",
      success_url: `${process.env.NEXT_PUBLIC_URL || "http://localhost:3000"}/acheme-coisas/publicado?id=${listingId}&payment=success`,
      cancel_url: `${process.env.NEXT_PUBLIC_URL || "http://localhost:3000"}/acheme-coisas/publicado?id=${listingId}&payment=cancelled`,
      metadata: {
        listingId,
        userId: user.id,
        productType,
        listingTitle: listing.title,
      },
      customer_email: user.email,
    });

    return NextResponse.json({ url: session.url });
  } catch (error: any) {
    console.error("Erro ao criar sess├úo de checkout:", error);
    return NextResponse.json(
      { error: error.message || "Erro ao criar sess├úo de pagamento" },
      { status: 500 }
    );
  }
}

import { NextResponse } from 'next/server';
import { createServerSupabaseClient } from '@/lib/supabaseServer';

// POST /api/proposals - Create a new proposal
export async function POST(req: Request) {
  const supabase = createServerSupabaseClient();
  const { data: { user } } = await supabase.auth.getUser();
  
  if (!user) {
    return NextResponse.json({ error: 'Not authenticated' }, { status: 401 });
  }

  try {
    const body = await req.json();
    const { ad_id, amount, visit_id, message } = body;

    if (!ad_id || !amount) {
      return NextResponse.json({ error: 'Missing required fields' }, { status: 400 });
    }

    // Verify user profile state (must have completed profile and be verified)
    const { data: profile } = await supabase
      .from('user_profiles')
      .select('profile_completed, verified, can_place_bids')
      .eq('id', user.id)
      .single();

    if (!profile || !profile.profile_completed || !profile.verified) {
      return NextResponse.json({ error: 'Profile incomplete or not verified' }, { status: 403 });
    }

    // Check for a completed visit for this ad
    const { data: visits } = await supabase
      .from('visits')
      .select('id, status')
      .eq('ad_id', ad_id)
      .eq('user_id', user.id)
      .eq('status', 'completed')
      .limit(1);

    let authorizedViaCode = false;

    if ((!visits || visits.length === 0) && body.auth_code) {
      // Validate authorization code (one-time use)
      const { data: codeRow } = await supabase
        .from('authorization_codes')
        .select('id, used')
        .eq('code', body.auth_code)
        .eq('property_id', ad_id)
        .eq('used', false)
        .single();

      if (codeRow) {
        // mark code as used
        await supabase
          .from('authorization_codes')
          .update({ used: true, used_at: new Date().toISOString() })
          .eq('id', codeRow.id);

        authorizedViaCode = true;
      }
    }

    if ((!visits || visits.length === 0) && !authorizedViaCode) {
      return NextResponse.json({ error: 'You must complete a visit or provide a valid authorization code', code: 'VISIT_REQUIRED' }, { status: 403 });
    }

    const { data, error } = await supabase
      .from('proposals')
      .insert({
        property_id: ad_id,  // Using property_id to match schema
        user_id: user.id,
        // visit_id: visit_id || visits[0]?.id,  // Optional
        amount,
        message,
        status: 'pending',
      })
      .select()
      .single();

    if (error) {
      return NextResponse.json({ error: error.message }, { status: 400 });
    }

    return NextResponse.json({ success: true, proposal: data });
  } catch (error: any) {
    return NextResponse.json({ error: error.message }, { status: 500 });
  }
}

// GET /api/proposals - Get user's proposals
export async function GET(_req: Request) {
  const supabase = createServerSupabaseClient();
  const { data: { user } } = await supabase.auth.getUser();
  
  if (!user) {
    return NextResponse.json({ error: 'Not authenticated' }, { status: 401 });
  }

  const { data, error } = await supabase
    .from('proposals')
    .select('*')
    .eq('user_id', user.id)
    .order('created_at', { ascending: false });

  if (error) {
    return NextResponse.json({ error: error.message }, { status: 400 });
  }

  return NextResponse.json(data);
}

import { NextResponse } from "next/server";
import { createServerSupabaseClient } from "@/lib/supabaseServer";

interface ScheduleVisitData {
  nome: string;
  email: string;
  telefone: string;
  cpf: string; // Changed from 'documento'
  birth_date?: string; // Required for guest users
  cidade: string;
  estado: string;
  pais: string;
  dataPreferencia: string;
  horarioPreferencia: string;
  mensagem?: string;
  visitType: "presencial" | "video";
  propertyId?: string;
  propertyTitle?: string;
  isGuest?: boolean; // Flag to trigger background check
  user_id?: string; // For authenticated users
}

/**
 * ENHANCED VISIT SCHEDULING WITH GUEST SUPPORT
 * 
 * Flow:
 * 1. Authenticated users ÔåÆ Schedule directly
 * 2. Guest users ÔåÆ Collect info + Run background checks
 * 3. If checks pass ÔåÆ Create pending_verification record + Schedule visit
 * 4. Admin confirms visit ÔåÆ If first visit, enable can_place_bids
 */

export async function POST(req: Request): Promise<NextResponse> {
  const supabase = createServerSupabaseClient();
  
  try {
    const body: ScheduleVisitData = await req.json();

    const {
      nome,
      email,
      telefone,
      cpf, // Changed from documento
      birth_date,
      cidade,
      estado,
      pais,
      dataPreferencia,
      horarioPreferencia,
      mensagem,
      visitType,
      propertyId,
      propertyTitle,
      isGuest,
      user_id
    } = body;

    // Valida├º├úo b├ísica
    if (!nome || !email || !telefone || !cpf || !dataPreferencia || !horarioPreferencia) {
      return NextResponse.json(
        { error: "Campos obrigat├│rios: nome, email, telefone, cpf, data e hor├írio." },
        { status: 400 }
      );
    }
    
    // Guest users require birth_date for background check
    if (isGuest && !birth_date) {
      return NextResponse.json(
        { error: "Data de nascimento ├® obrigat├│ria para novos usu├írios." },
        { status: 400 }
      );
    }
    
    const cleanCPF = cpf.replace(/\D/g, '');

    // Get authenticated user if not explicitly guest
    let authenticatedUser = null;
    if (!isGuest) {
      const { data: { user } } = await supabase.auth.getUser();
      authenticatedUser = user;
    }

    // ============================================
    // GUEST USER FLOW - With Background Checks
    // ============================================
    
    if (isGuest || !authenticatedUser) {
      
      // 1. Check if CPF already exists (prevent duplicate registrations)
      const { data: existingProfile } = await supabase
        .from('user_profiles')
        .select('id, full_name')
        .eq('cpf', cleanCPF)
        .single();
      
      if (existingProfile) {
        return NextResponse.json({ 
          error: 'Este CPF j├í est├í cadastrado. Por favor, fa├ºa login para agendar sua visita.',
          code: 'CPF_EXISTS'
        }, { status: 400 });
      }
      
      // 2. Check if already has pending verification
      const { data: existingPending } = await supabase
        .from('pending_verifications')
        .select('id, verification_status')
        .eq('cpf', cleanCPF)
        .eq('account_created', false)
        .single();
      
      if (existingPending) {
        if (existingPending.verification_status === 'rejected') {
          return NextResponse.json({ 
            error: 'N├úo foi poss├¡vel processar sua solicita├º├úo. Entre em contato para mais informa├º├Áes.',
            code: 'REGISTRATION_DENIED'
          }, { status: 403 });
        }
        
        if (existingPending.verification_status === 'pending' || existingPending.verification_status === 'in_progress') {
          return NextResponse.json({ 
            message: 'Sua verifica├º├úo ainda est├í em andamento. Voc├¬ receber├í um email quando conclu├¡da.',
            code: 'PENDING_REVIEW',
            verification_id: existingPending.id
          }, { status: 202 });
        }
      }
      
      // 3. Validate CPF
      const cpfValidation = await fetch(`${process.env.NEXT_PUBLIC_APP_URL}/api/verify-cpf`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ cpf: cleanCPF, full_name: nome, birth_date })
      });
      
      const cpfResult = await cpfValidation.json();
      
      if (!cpfResult.valid) {
        return NextResponse.json({ 
          error: 'CPF inv├ílido. Por favor, verifique e tente novamente.',
          details: cpfResult.error
        }, { status: 400 });
      }
      
      // 4. Create Pending Verification Record
      const { data: pendingVerification, error: pendingError } = await supabase
        .from('pending_verifications')
        .insert({
          full_name: nome,
          email,
          cpf: cleanCPF,
          phone: telefone,
          birth_date,
          city: cidade,
          state: estado,
          country: pais || 'Brasil',
          source: 'visit_request',
          source_id: propertyId || null,
          cpf_validation_status: 'approved',
          cpf_validated_at: new Date().toISOString()
        })
        .select()
        .single();
      
      if (pendingError) {
        console.error('Error creating pending verification:', pendingError);
        return NextResponse.json({ 
          error: 'Falha ao processar solicita├º├úo' 
        }, { status: 500 });
      }
      
      // 5. Run Background Checks
      const backgroundCheck = await fetch(`${process.env.NEXT_PUBLIC_APP_URL}/api/background-check`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          cpf: cleanCPF,
          full_name: nome,
          birth_date,
          email,
          pending_verification_id: pendingVerification.id
        })
      });
      
      const backgroundResult = await backgroundCheck.json();
      
      // 6. Handle Background Check Results
      if (backgroundResult.status === 'rejected') {
        // Silent rejection - don't reveal reason to user
        return NextResponse.json({ 
          error: 'N├úo foi poss├¡vel processar sua solicita├º├úo no momento. Por favor, entre em contato conosco.',
          code: 'REGISTRATION_DENIED'
        }, { status: 403 });
      }
      
      if (backgroundResult.status === 'needs_review') {
        // Manual review required
        return NextResponse.json({ 
          message: 'Sua solicita├º├úo est├í em an├ílise. Voc├¬ receber├í um email dentro de 24-48 horas.',
          code: 'PENDING_REVIEW',
          verification_id: pendingVerification.id
        }, { status: 202 });
      }
      
      // 7. APPROVED - Create Visit Request
      const scheduledAt = new Date(`${dataPreferencia}T${horarioPreferencia || '09:00'}`).toISOString();
      
      const { data: visitData, error: visitError } = await supabase
        .from("visits")
        .insert([
          {
            ad_id: propertyId || null,
            user_id: null, // No user account yet
            guest_name: nome,
            guest_email: email,
            guest_phone: telefone,
            guest_cpf: cleanCPF,
            guest_birth_date: birth_date,
            verification_pending_id: pendingVerification.id,
            background_check_required: true,
            background_check_completed: true,
            background_check_passed: true,
            visit_type: visitType === "presencial" ? "in_person" : "video",
            scheduled_at: scheduledAt,
            status: "pending", // Will be confirmed after account creation
            notes: mensagem || null,
          },
        ])
        .select()
        .single();
      
      if (visitError) {
        console.error("Erro ao criar visita:", visitError);
        return NextResponse.json({ error: visitError.message }, { status: 500 });
      }
      
      // 8. Auto-create account if background check passed
      if (backgroundResult.status === 'approved') {
        // Generate random password
        const randomPassword = `${Math.random().toString(36).slice(-8)}${Math.random().toString(36).slice(-8)}`;
        
        const { data: authData, error: authError } = await supabase.auth.admin.createUser({
          email,
          password: randomPassword,
          email_confirm: true,
          user_metadata: {
            full_name: nome,
            phone: telefone
          }
        });
        
        if (!authError && authData.user) {
          // Create user profile
          await supabase
            .from('user_profiles')
            .insert({
              id: authData.user.id,
              full_name: nome,
              cpf: cleanCPF,
              phone: telefone,
              birth_date,
              city: cidade,
              state: estado,
              profile_completed: true,
              verified: true,
              can_schedule_visits: true,
              can_place_bids: false, // Only after visit completion
              cpf_validation_status: 'approved',
              cpf_validated_at: new Date().toISOString(),
              federal_police_check_status: 'approved',
              federal_police_check_date: new Date().toISOString(),
              interpol_check_status: 'approved',
              interpol_check_date: new Date().toISOString(),
              background_check_completed: true,
              background_check_passed: true,
              verified_at: new Date().toISOString()
            });
          
          // Update pending verification
          await supabase
            .from('pending_verifications')
            .update({
              account_created: true,
              user_id: authData.user.id
            })
            .eq('id', pendingVerification.id);
          
          // Update visit with user_id
          await supabase
            .from('visits')
            .update({ user_id: authData.user.id })
            .eq('id', visitData.id);
          
          // TODO: Send welcome email with credentials
        }
      }
      
      return NextResponse.json({ 
        success: true,
        message: backgroundResult.status === 'approved' ? 
          'Visita agendada com sucesso! Sua conta foi criada - verifique seu email.' : 
          'Solicita├º├úo recebida! Entraremos em contato em breve.'
      }, { status: 201 });
    }

    // ============================================
    // AUTHENTICATED USER FLOW - Simple Scheduling
    // ============================================
    
    const scheduledAt = new Date(`${dataPreferencia}T${horarioPreferencia || '09:00'}`).toISOString();

    const { data, error } = await supabase
      .from("visits")
      .insert([
        {
          ad_id: propertyId || null,
          user_id: user_id || authenticatedUser?.id || null,
          guest_name: nome,
          guest_email: email,
          guest_phone: telefone,
          visit_type: visitType === "presencial" ? "in_person" : "video",
          scheduled_at: scheduledAt,
          status: "requested",
          notes: mensagem || null,
        },
      ])
      .select()
      .single();

    if (error) {
      console.error("Erro ao agendar visita:", error);
      return NextResponse.json({ error: error.message }, { status: 500 });
    }

    // TODO: Send email notification to admin and user

    return NextResponse.json({ 
      data,
      message: "Visita agendada com sucesso! Entraremos em contato em breve." 
    }, { status: 201 });
    
  } catch (err) {
    const message =
      err instanceof Error ? err.message : "Erro desconhecido ao agendar visita.";

    console.error("Erro no endpoint /api/schedule-visit:", message);

    return NextResponse.json({ error: message }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from "next/server";
import { supabase } from "@/lib/supabaseClient";

function tableForSection(section: string) {
  // Mapping rules: map known site sections to the DB tables we manage.
  // Extend this mapping as new domain-specific tables are added.
  const s = (section || "").toLowerCase();
  if (s === "properties" || s === "imoveis") return "properties";
  if (s === "sitios" || s === "projetos" || s === "carcara") return "properties";
  // Motors, machinery and marine currently live in the generic listings table.
  if (s === "motors" || s === "machina" || s === "marine" || s === "motors" || s === "classificados" || s === "acheme-coisas") return "listings";
  // Default fallback
  return "listings";
}

export async function GET(req: NextRequest) {
  // Auto-suggest endpoint: /api/search?q=...&section=...
  try {
    const { searchParams } = new URL(req.url);
    const q = searchParams.get("q") || "";
    const section = searchParams.get("section") || "listings";

    if (!q || q.length < 2) return NextResponse.json({ suggestions: [] });

    const table = tableForSection(section);
    // search title/name and description - tuned per-table
    const ilike = `%${q}%`;

    // Select sensible suggestion fields depending on table
    const selectFields = table === "properties" ? "id,title,slug" : "id,title,name,brand,model,slug";

    // Build OR filters depending on available fields for the table
    const orParts: string[] = [];
    orParts.push(`title.ilike.${ilike}`);
    orParts.push(`name.ilike.${ilike}`);
    orParts.push(`slug.ilike.${ilike}`);
    orParts.push(`description.ilike.${ilike}`);
    if (table === "listings") {
      // For vehicle/machinery listings, also search brand/model
      orParts.push(`brand.ilike.${ilike}`);
      orParts.push(`model.ilike.${ilike}`);
    }

    const orFilter = orParts.join(",");

    const { data, error } = await supabase
      .from(table)
      .select(selectFields)
      .or(orFilter)
      .limit(8);

    if (error) {
      return NextResponse.json({ error: error.message }, { status: 500 });
    }

    return NextResponse.json({ suggestions: data || [] });
  } catch (err) {
    return NextResponse.json({ error: (err as Error).message || "unknown" }, { status: 500 });
  }
}

export async function POST(req: NextRequest) {
  try {
    const body = await req.json();
    const {
      section = "properties",
      query = "",
      category,
      subcategory,
      priceMin,
      priceMax,
      areaMin,
      areaMax,
      sortBy = "newest",
      limit = 20,
      offset = 0,
    } = body || {};

    const table = tableForSection(section);
    let qb: any = supabase.from(table).select("*", { count: "exact" });

    // Full-text-ish filters (simple ilike ranges for now)
    if (query) {
      const ilike = `%${query}%`;
      const orParts = [`title.ilike.${ilike}`, `description.ilike.${ilike}`, `location.ilike.${ilike}`];
      if (table === "listings") {
        orParts.push(`name.ilike.${ilike}`, `brand.ilike.${ilike}`, `model.ilike.${ilike}`);
      }
      qb = qb.or(orParts.join(","));
    }

    // Numeric filters
    if (priceMin !== undefined && priceMin !== null) qb = qb.gte("price", Number(priceMin));
    if (priceMax !== undefined && priceMax !== null) qb = qb.lte("price", Number(priceMax));

    if (areaMin !== undefined && areaMin !== null) qb = qb.gte("area_total", Number(areaMin));
    if (areaMax !== undefined && areaMax !== null) qb = qb.lte("area_total", Number(areaMax));

    // Section-specific filters (vehicles / machinery)
    if (body.brand) qb = qb.eq("brand", body.brand);
    if (body.model) qb = qb.eq("model", body.model);
    if (body.yearMin !== undefined && body.yearMin !== null) qb = qb.gte("year", Number(body.yearMin));
    if (body.yearMax !== undefined && body.yearMax !== null) qb = qb.lte("year", Number(body.yearMax));

    if (category) qb = qb.eq("category", category);
    if (subcategory) qb = qb.eq("subcategory", subcategory);

    // Sorting
    switch (sortBy) {
      case "price_asc":
        qb = qb.order("price", { ascending: true });
        break;
      case "price_desc":
        qb = qb.order("price", { ascending: false });
        break;
      case "area_desc":
        qb = qb.order("area_total", { ascending: false });
        break;
      case "year_desc":
        qb = qb.order("year", { ascending: false });
        break;
      case "newest":
      default:
        qb = qb.order("created_at", { ascending: false });
        break;
    }

    qb = qb.range(Number(offset), Number(offset) + Number(limit) - 1);

    const { data, error, count } = await qb;

    if (error) return NextResponse.json({ error: error.message }, { status: 500 });

    return NextResponse.json({ data: data || [], count: count || 0 });
  } catch (err) {
    return NextResponse.json({ error: (err as Error).message || "unknown" }, { status: 500 });
  }
}

import { NextResponse } from 'next/server';
import { createServerSupabaseClient } from '@/lib/supabaseServer';

/**
 * NEW SIGNUP FLOW WITH BACKGROUND CHECKS
 * 
 * 1. Collect user information
 * 2. Validate CPF
 * 3. Run background checks (Federal Police + Interpol)
 * 4. If PASS ÔåÆ Create account immediately + notify
 * 5. If FAIL ÔåÆ Reject silently (or with generic message)
 * 6. If NEEDS_REVIEW ÔåÆ Create pending_verification record + notify admin
 */

export async function POST(req: Request) {
  const supabase = createServerSupabaseClient();
  
  try {
    const {
      email,
      password,
      full_name,
      cpf,
      phone,
      birth_date,
      // Optional address fields
      cep,
      street,
      number,
      complement,
      neighborhood,
      city,
      state
    } = await req.json();
    
    // ============================================
    // 1. Validate Required Fields
    // ============================================
    
    if (!email || !password || !full_name || !cpf || !birth_date) {
      return NextResponse.json({ 
        error: 'Missing required fields: email, password, full_name, cpf, birth_date' 
      }, { status: 400 });
    }
    
    const cleanCPF = cpf.replace(/\D/g, '');
    
    // ============================================
    // 2. Check if CPF or Email Already Exists
    // ============================================
    
    const { data: existingProfile } = await supabase
      .from('user_profiles')
      .select('id')
      .eq('cpf', cleanCPF)
      .single();
    
    if (existingProfile) {
      return NextResponse.json({ 
        error: 'CPF already registered' 
      }, { status: 400 });
    }
    
    // ============================================
    // 3. Validate CPF
    // ============================================
    
    const cpfValidation = await fetch(`${process.env.NEXT_PUBLIC_APP_URL}/api/verify-cpf`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ cpf: cleanCPF, full_name, birth_date })
    });
    
    const cpfResult = await cpfValidation.json();
    
    if (!cpfResult.valid) {
      return NextResponse.json({ 
        error: 'Invalid CPF',
        details: cpfResult.error
      }, { status: 400 });
    }
    
    // ============================================
    // 4. Create Pending Verification Record
    // ============================================
    
    const { data: pendingVerification, error: pendingError } = await supabase
      .from('pending_verifications')
      .insert({
        full_name,
        email,
        cpf: cleanCPF,
        phone,
        birth_date,
        cep,
        street,
        number,
        complement,
        neighborhood,
        city,
        state,
        source: 'signup',
        cpf_validation_status: 'approved',
        cpf_validated_at: new Date().toISOString()
      })
      .select()
      .single();
    
    if (pendingError) {
      console.error('Error creating pending verification:', pendingError);
      return NextResponse.json({ 
        error: 'Failed to process signup request' 
      }, { status: 500 });
    }
    
    // ============================================
    // 5. Run Background Checks
    // ============================================
    
    const backgroundCheck = await fetch(`${process.env.NEXT_PUBLIC_APP_URL}/api/background-check`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        cpf: cleanCPF,
        full_name,
        birth_date,
        email,
        pending_verification_id: pendingVerification.id
      })
    });
    
    const backgroundResult = await backgroundCheck.json();
    
    // ============================================
    // 6. Handle Results
    // ============================================
    
    if (backgroundResult.status === 'rejected') {
      // REJECTED: Don't create account, don't tell user why
      return NextResponse.json({ 
        error: 'Unable to complete registration at this time. Please contact support if you believe this is an error.',
        code: 'REGISTRATION_DENIED'
      }, { status: 403 });
    }
    
    if (backgroundResult.status === 'needs_review') {
      // NEEDS MANUAL REVIEW: Notify admin, ask user to wait
      // TODO: Send email to admin for manual review
      
      return NextResponse.json({ 
        message: 'Your registration is under review. We will notify you via email within 24-48 hours.',
        code: 'PENDING_REVIEW',
        verification_id: pendingVerification.id
      }, { status: 202 }); // 202 Accepted (processing)
    }
    
    // ============================================
    // 7. APPROVED: Create Account Immediately
    // ============================================
    
    if (backgroundResult.status === 'approved') {
      // Create auth user
      const { data: authData, error: authError } = await supabase.auth.admin.createUser({
        email,
        password,
        email_confirm: true, // Auto-confirm email for verified users
        user_metadata: {
          full_name,
          phone
        }
      });
      
      if (authError) {
        console.error('Error creating auth user:', authError);
        return NextResponse.json({ 
          error: 'Failed to create account',
          details: authError.message
        }, { status: 500 });
      }
      
      // Create user profile with verification flags
      const { error: profileError } = await supabase
        .from('user_profiles')
        .insert({
          id: authData.user.id,
          full_name,
          cpf: cleanCPF,
          phone,
          birth_date,
          cep,
          street,
          number,
          complement,
          neighborhood,
          city,
          state,
          profile_completed: true,
          verified: true, // Already verified!
          can_schedule_visits: true,
          can_place_bids: false, // Only after first visit completion
          cpf_validation_status: 'approved',
          cpf_validated_at: new Date().toISOString(),
          federal_police_check_status: 'approved',
          federal_police_check_date: new Date().toISOString(),
          interpol_check_status: 'approved',
          interpol_check_date: new Date().toISOString(),
          background_check_completed: true,
          background_check_passed: true,
          verified_at: new Date().toISOString()
        });
      
      if (profileError) {
        console.error('Error creating profile:', profileError);
        // Try to clean up auth user
        await supabase.auth.admin.deleteUser(authData.user.id);
        return NextResponse.json({ 
          error: 'Failed to complete registration',
          details: profileError.message
        }, { status: 500 });
      }
      
      // Update pending verification record
      await supabase
        .from('pending_verifications')
