    }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { createRouteHandlerClient } from '@supabase/auth-helpers-nextjs';
import { cookies } from 'next/headers';

/**
 * POST /api/verification/check-criminal
 * Check criminal background using Serasa Experian API
 * 
 * This requires SERASA_API_KEY and SERASA_API_SECRET environment variables
 * Serasa pricing: R$5-15 per background check depending on depth
 * 
 * API Docs: https://desenvolvedores.serasaexperian.com.br/
 */
export async function POST(_request: NextRequest) {
  try {
    const supabase = createRouteHandlerClient({ cookies });

    // Check authentication
    const { data: { user }, error: authError } = await supabase.auth.getUser();
    if (authError || !user) {
      return NextResponse.json(
        { error: 'N├úo autenticado.' },
        { status: 401 }
      );
    }

    // Get verification record
    const { data: verification, error: verifyError } = await supabase
      .from('user_verifications')
      .select('*')
      .eq('user_id', user.id)
      .single();

    if (verifyError || !verification) {
      return NextResponse.json(
        { error: 'Verifica├º├úo n├úo encontrada.' },
        { status: 404 }
      );
    }

    if (!verification.cpf || !verification.cpf_valid) {
      return NextResponse.json(
        { error: 'CPF deve ser validado primeiro.' },
        { status: 400 }
      );
    }

    // Check if Serasa API credentials are configured
    const serasaApiKey = process.env.SERASA_API_KEY;
    const serasaApiSecret = process.env.SERASA_API_SECRET;

    if (!serasaApiKey || !serasaApiSecret) {
      console.error('SERASA_API_KEY or SERASA_API_SECRET not configured');

      // In development, simulate background check
      if (process.env.NODE_ENV === 'development') {
        const mockResult = {
          criminal_record_status: 'clean',
          criminal_record_details: {
            has_pending_cases: false,
            has_convictions: false,
            serious_crimes: false,
            checked_at: new Date().toISOString(),
          },
          credit_score: 750,
          credit_status: 'good',
          credit_restrictions: [],
        };

        await supabase
          .from('user_verifications')
          .update({
            criminal_record_status: mockResult.criminal_record_status,
            criminal_record_details: mockResult.criminal_record_details,
            criminal_check_date: new Date().toISOString(),
            credit_score: mockResult.credit_score,
            credit_status: mockResult.credit_status,
            credit_restrictions: mockResult.credit_restrictions,
            credit_check_date: new Date().toISOString(),
            status: 'checking', // Trigger auto-verification rules
            updated_at: new Date().toISOString(),
          })
          .eq('id', verification.id);

        return NextResponse.json({
          message: 'Verifica├º├úo de antecedentes conclu├¡da (modo desenvolvimento).',
          ...mockResult,
        });
      }

      return NextResponse.json(
        { error: 'Servi├ºo de verifica├º├úo de antecedentes n├úo configurado.' },
        { status: 503 }
      );
    }

    // Get Serasa OAuth token
    const tokenResponse = await fetch('https://auth.serasaexperian.com.br/oauth/token', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/x-www-form-urlencoded',
        'Authorization': `Basic ${Buffer.from(`${serasaApiKey}:${serasaApiSecret}`).toString('base64')}`,
      },
      body: 'grant_type=client_credentials',
    });

    if (!tokenResponse.ok) {
      console.error('Failed to get Serasa token');
      return NextResponse.json(
        { error: 'Erro ao autenticar com servi├ºo de verifica├º├úo.' },
        { status: 500 }
      );
    }

    const { access_token } = await tokenResponse.json();

    // Call Serasa Background Check API
    const cpfClean = verification.cpf.replace(/\D/g, '');
    const serasaUrl = 'https://api.serasaexperian.com.br/background-check/v1/consulta';

    const serasaResponse = await fetch(serasaUrl, {
      method: 'POST',
      headers: {
        'Authorization': `Bearer ${access_token}`,
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        cpf: cpfClean,
        nome: verification.full_name,
        data_nascimento: verification.date_of_birth,
        checks: [
          'criminal_record',      // Antecedentes criminais
          'pending_cases',        // Processos pendentes
          'credit_score',         // Score de cr├®dito
          'credit_restrictions',  // Restri├º├Áes financeiras (SPC/Serasa)
        ],
      }),
    });

    if (!serasaResponse.ok) {
      const errorData = await serasaResponse.json().catch(() => ({}));
      console.error('Serasa API error:', errorData);
      
      return NextResponse.json(
        { error: 'Erro ao verificar antecedentes. Tente novamente.' },
        { status: 500 }
      );
    }

    const serasaData = await serasaResponse.json();

    // Parse Serasa response and categorize criminal history
    let criminalRecordStatus: string = 'clean';
    const criminalDetails: any = {
      has_pending_cases: false,
      has_convictions: false,
      serious_crimes: false,
      convictions: [],
      pending_cases: [],
      checked_at: new Date().toISOString(),
    };

    // Check for serious crimes (murder, rape, kidnapping, etc.)
    const seriousCrimeKeywords = [
      'homic├¡dio', 'latroc├¡nio', 'estupro', 'sequestro', 'extors├úo',
      'tr├ífico de drogas', 'associa├º├úo criminosa', 'organiza├º├úo criminosa'
    ];

    if (serasaData.criminal_record?.convictions?.length > 0) {
      criminalDetails.has_convictions = true;
      criminalDetails.convictions = serasaData.criminal_record.convictions;

      const hasSeriousCrimes = serasaData.criminal_record.convictions.some((conviction: any) =>
        seriousCrimeKeywords.some(keyword => 
          conviction.crime_type?.toLowerCase().includes(keyword)
        )
      );

      if (hasSeriousCrimes) {
        criminalRecordStatus = 'serious_crimes';
      } else {
        criminalRecordStatus = 'criminal_history';
      }
    }

    if (serasaData.pending_cases?.cases?.length > 0) {
      criminalDetails.has_pending_cases = true;
      criminalDetails.pending_cases = serasaData.pending_cases.cases;
      
      if (criminalRecordStatus === 'clean') {
        criminalRecordStatus = 'pending_cases';
      }
    }

    // Parse credit information
    const creditScore = serasaData.credit_score?.score || null;
    let creditStatus = 'not_checked';
    
    if (creditScore !== null) {
      if (creditScore >= 800) creditStatus = 'excellent';
      else if (creditScore >= 600) creditStatus = 'good';
      else if (creditScore >= 400) creditStatus = 'fair';
      else creditStatus = 'poor';
    }

    const creditRestrictions = serasaData.credit_restrictions?.restrictions || [];
    if (creditRestrictions.length > 0) {
      creditStatus = 'restricted';
    }

    // Update verification record with results
    // Setting status to 'checking' will trigger the auto-verification rules
    await supabase
      .from('user_verifications')
      .update({
        criminal_record_status: criminalRecordStatus,
        criminal_record_details: criminalDetails,
        criminal_check_date: new Date().toISOString(),
        credit_score: creditScore,
        credit_status: creditStatus,
        credit_restrictions: creditRestrictions,
        credit_check_date: new Date().toISOString(),
        external_check_provider: 'serasa',
        external_check_response: serasaData,
        status: 'checking', // This triggers the auto-verification rules
        updated_at: new Date().toISOString(),
      })
      .eq('id', verification.id);

    // Log event
    await supabase.from('verification_audit_log').insert({
      user_verification_id: verification.id,
      user_id: user.id,
      event_type: 'automated_check_completed',
      performed_by_type: 'system',
      event_data: {
        check_type: 'criminal_background',
        provider: 'serasa',
        criminal_record_status: criminalRecordStatus,
        credit_status: creditStatus,
        has_convictions: criminalDetails.has_convictions,
        has_pending_cases: criminalDetails.has_pending_cases,
      },
    });

    return NextResponse.json({
      message: 'Verifica├º├úo de antecedentes conclu├¡da.',
      criminal_record_status: criminalRecordStatus,
      criminal_details: {
        has_convictions: criminalDetails.has_convictions,
        has_pending_cases: criminalDetails.has_pending_cases,
        serious_crimes: criminalDetails.serious_crimes,
      },
      credit_score: creditScore,
      credit_status: creditStatus,
      next_step: 'face_verification',
    });

  } catch (error) {
    console.error('Error checking criminal background:', error);
    return NextResponse.json(
      { error: 'Erro ao verificar antecedentes. Tente novamente.' },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { createRouteHandlerClient } from '@supabase/auth-helpers-nextjs';
import { cookies } from 'next/headers';

/**
 * POST /api/verification/upload-documents
 * Upload verification documents (ID front/back, selfie, proof of address)
 */
export async function POST(request: NextRequest) {
  try {
    const supabase = createRouteHandlerClient({ cookies });

    // Check authentication
    const { data: { user }, error: authError } = await supabase.auth.getUser();
    if (authError || !user) {
      return NextResponse.json(
        { error: 'N├úo autenticado.' },
        { status: 401 }
      );
    }

    // Get form data
    const formData = await request.formData();
    const documentFront = formData.get('document_front') as File | null;
    const documentBack = formData.get('document_back') as File | null;
    const selfie = formData.get('selfie') as File | null;
    const proofOfAddress = formData.get('proof_of_address') as File | null;
    const documentType = formData.get('document_type') as string;
    const documentNumber = formData.get('document_number') as string;

    // Validate required files
    if (!documentFront || !selfie) {
      return NextResponse.json(
        { error: 'Frente do documento e selfie s├úo obrigat├│rios.' },
        { status: 400 }
      );
    }

    // Get verification record
    const { data: verification, error: verifyError } = await supabase
      .from('user_verifications')
      .select('id, status')
      .eq('user_id', user.id)
      .single();

    if (verifyError || !verification) {
      return NextResponse.json(
        { error: 'Verifica├º├úo n├úo encontrada. Inicie a verifica├º├úo primeiro.' },
        { status: 404 }
      );
    }

    if (verification.status === 'approved') {
      return NextResponse.json(
        { error: 'Voc├¬ j├í est├í verificado.' },
        { status: 400 }
      );
    }

    // Upload files to Supabase Storage
    const uploadedFiles: { [key: string]: string } = {};

    // Upload document front
    const frontFileName = `${user.id}/document-front-${Date.now()}.${documentFront.name.split('.').pop()}`;
    const { data: frontData, error: frontError } = await supabase.storage
      .from('verification-documents')
      .upload(frontFileName, documentFront, {
        contentType: documentFront.type,
        upsert: true,
      });

    if (frontError) {
      console.error('Error uploading document front:', frontError);
      return NextResponse.json(
        { error: 'Erro ao fazer upload da frente do documento.' },
        { status: 500 }
      );
    }

    const { data: { publicUrl: frontUrl } } = supabase.storage
      .from('verification-documents')
      .getPublicUrl(frontFileName);
    uploadedFiles.document_front_url = frontUrl;

    // Upload document back (if provided)
    if (documentBack) {
      const backFileName = `${user.id}/document-back-${Date.now()}.${documentBack.name.split('.').pop()}`;
      const { data: backData, error: backError } = await supabase.storage
        .from('verification-documents')
        .upload(backFileName, documentBack, {
          contentType: documentBack.type,
          upsert: true,
        });

      if (!backError) {
        const { data: { publicUrl: backUrl } } = supabase.storage
          .from('verification-documents')
          .getPublicUrl(backFileName);
        uploadedFiles.document_back_url = backUrl;
      }
    }

    // Upload selfie
    const selfieFileName = `${user.id}/selfie-${Date.now()}.${selfie.name.split('.').pop()}`;
    const { data: selfieData, error: selfieError } = await supabase.storage
      .from('verification-documents')
      .upload(selfieFileName, selfie, {
        contentType: selfie.type,
        upsert: true,
      });

    if (selfieError) {
      console.error('Error uploading selfie:', selfieError);
      return NextResponse.json(
        { error: 'Erro ao fazer upload da selfie.' },
        { status: 500 }
      );
    }

    const { data: { publicUrl: selfieUrl } } = supabase.storage
      .from('verification-documents')
      .getPublicUrl(selfieFileName);
    uploadedFiles.selfie_url = selfieUrl;

    // Upload proof of address (if provided)
    if (proofOfAddress) {
      const addressFileName = `${user.id}/proof-of-address-${Date.now()}.${proofOfAddress.name.split('.').pop()}`;
      const { data: addressData, error: addressError } = await supabase.storage
        .from('verification-documents')
        .upload(addressFileName, proofOfAddress, {
          contentType: proofOfAddress.type,
          upsert: true,
        });

      if (!addressError) {
        const { data: { publicUrl: addressUrl } } = supabase.storage
          .from('verification-documents')
          .getPublicUrl(addressFileName);
        uploadedFiles.proof_of_address_url = addressUrl;
      }
    }

    // Update verification record with document URLs
    const { error: updateError } = await supabase
      .from('user_verifications')
      .update({
        document_type: documentType,
        document_number: documentNumber,
        ...uploadedFiles,
        updated_at: new Date().toISOString(),
      })
      .eq('id', verification.id);

    if (updateError) {
      throw updateError;
    }

    // Log event
    await supabase.from('verification_audit_log').insert({
      user_verification_id: verification.id,
      user_id: user.id,
      event_type: 'document_uploaded',
      performed_by: user.id,
      performed_by_type: 'user',
      event_data: {
        document_type: documentType,
        files_uploaded: Object.keys(uploadedFiles),
      },
    });

    return NextResponse.json({
      message: 'Documentos enviados com sucesso.',
      uploaded_files: Object.keys(uploadedFiles),
      next_step: 'automated_checks',
    });

  } catch (error) {
    console.error('Error uploading documents:', error);
    return NextResponse.json(
      { error: 'Erro ao enviar documentos. Tente novamente.' },
      { status: 500 }
    );
  }
}

import { NextResponse } from 'next/server';
import { createServerSupabaseClient } from '@/lib/supabaseServer';

/**
 * CPF Validation API
 * Validates CPF format and checks with Brazilian Federal Revenue (Receita Federal)
 */

// CPF validation algorithm
function validateCPF(cpf: string): boolean {
  cpf = cpf.replace(/\D/g, '');
  
  if (cpf.length !== 11 || /^(\d)\1{10}$/.test(cpf)) {
    return false;
  }
  
  let sum = 0;
  let remainder;
  
  for (let i = 1; i <= 9; i++) {
    sum += parseInt(cpf.substring(i - 1, i)) * (11 - i);
  }
  
  remainder = (sum * 10) % 11;
  if (remainder === 10 || remainder === 11) remainder = 0;
  if (remainder !== parseInt(cpf.substring(9, 10))) return false;
  
  sum = 0;
  for (let i = 1; i <= 10; i++) {
    sum += parseInt(cpf.substring(i - 1, i)) * (12 - i);
  }
  
  remainder = (sum * 10) % 11;
  if (remainder === 10 || remainder === 11) remainder = 0;
  if (remainder !== parseInt(cpf.substring(10, 11))) return false;
  
  return true;
}

export async function POST(req: Request) {
  const supabase = createServerSupabaseClient();
  
  try {
    const { cpf, full_name, birth_date } = await req.json();
    
    if (!cpf) {
      return NextResponse.json({ error: 'CPF is required' }, { status: 400 });
    }
    
    // Clean CPF
    const cleanCPF = cpf.replace(/\D/g, '');
    
    // Basic validation
    const isValid = validateCPF(cleanCPF);
    
    if (!isValid) {
      return NextResponse.json({ 
        valid: false, 
        error: 'Invalid CPF format' 
      }, { status: 400 });
    }
    
    // TODO: Integration with Receita Federal API
    // For now, we'll do basic validation
    // In production, you would call:
    // - Receita Federal API to verify CPF is real and matches name/birth date
    // - Check if CPF is not blacklisted
    
    // Simulated API call delay
    await new Promise(resolve => setTimeout(resolve, 500));
    
    // Log validation attempt
    await supabase.from('verification_logs').insert({
      user_id: null, // No user yet
      verification_type: 'cpf',
      status: isValid ? 'approved' : 'rejected',
