"use client";

import { useState, useEffect } from "react";
import { supabase } from "@/lib/supabaseClient";
import Link from "next/link";
import Image from "next/image";
import { X, ArrowLeft, Share2, Download, MapPin, Maximize2, DollarSign } from "lucide-react";
import Breadcrumbs from "@/components/Breadcrumbs";

interface Property {
  id: string;
  title: string;
  location: string;
  price: number;
  area_total: number;
  fotos: string[];
  description: string;
  agua: boolean;
  energia: boolean;
  internet: boolean;
}

interface ComparisonRow {
  label: string;
  key: keyof Property | 'preco_ha';
  icon?: any;
  suffix?: string;
  format?: (value: any) => string;
}

export default function ComparePage() {
  const [properties, setProperties] = useState<Property[]>([]);
  const [loading, setLoading] = useState(true);
  const [selectedIds, setSelectedIds] = useState<string[]>([]);

  useEffect(() => {
    // Load selected property IDs from URL params
    const params = new URLSearchParams(window.location.search);
    const ids = params.get("ids")?.split(",").filter(Boolean) || [];
    setSelectedIds(ids);
    
    if (ids.length > 0) {
      void loadProperties(ids);
    } else {
      setLoading(false);
    }
  }, []);

  const loadProperties = async (ids: string[]) => {
    try {
      const { data, error } = await supabase
        .from("properties")
        .select("*")
        .in("id", ids);

      if (error) throw error;
      setProperties(data || []);
    } catch (error) {
      console.error("Error loading properties:", error);
    } finally {
      setLoading(false);
    }
  };

  const removeProperty = (id: string) => {
    const newIds = selectedIds.filter(selectedId => selectedId !== id);
    setSelectedIds(newIds);
    setProperties(properties.filter(p => p.id !== id));
    
    // Update URL
    const url = new URL(window.location.href);
    url.searchParams.set("ids", newIds.join(","));
    window.history.pushState({}, "", url);
  };

  const shareComparison = () => {
    const url = window.location.href;
    void navigator.clipboard.writeText(url);
    alert("Link copiado! Compartilhe com sua fam├¡lia ou s├│cio.");
  };

  const downloadPDF = () => {
    // TODO: Implement PDF generation
    alert("Funcionalidade de download PDF em desenvolvimento!");
  };

  if (loading) {
    return (
      <div className="min-h-screen bg-[#0a0a0a] flex items-center justify-center">
        <div className="text-center">
          <div className="animate-spin w-16 h-16 border-4 border-[#A8C97F] border-t-transparent rounded-full mx-auto mb-4"></div>
          <p className="text-[#8B9B6E]">Carregando compara├º├úo...</p>
        </div>
      </div>
    );
  }

  if (properties.length === 0) {
    return (
      <div className="min-h-screen bg-[#0a0a0a]">
        <div className="max-w-7xl mx-auto px-4 py-8">
          <Link
            href="/imoveis"
            className="inline-flex items-center gap-2 text-[#8B9B6E] hover:text-[#A8C97F] transition-colors mb-6"
          >
            <ArrowLeft className="w-5 h-5" />
            Voltar para Propriedades
          </Link>

          <div className="text-center py-20">
            <div className="w-32 h-32 mx-auto mb-6 bg-[#2a2a1a] rounded-full flex items-center justify-center">
              <MapPin className="w-16 h-16 text-[#676767]" />
            </div>
            <h2 className="text-2xl font-bold text-[#E6C98B] mb-3">
              Nenhuma propriedade selecionada
            </h2>
            <p className="text-[#8B9B6E] mb-6">
              Selecione at├® 3 propriedades para comparar
            </p>
            <Link
              href="/imoveis"
              className="inline-block px-6 py-3 bg-gradient-to-r from-[#A8C97F] to-[#0D7377] text-[#0a0a0a] font-bold rounded-full hover:scale-105 transition-all"
            >
              Buscar Propriedades
            </Link>
          </div>
        </div>
      </div>
    );
  }

  const comparisonRows: ComparisonRow[] = [
    { label: "Localiza├º├úo", key: "location", icon: MapPin },
    { label: "├ürea Total", key: "area_total", suffix: " hectares", icon: Maximize2 },
    { label: "Pre├ºo", key: "price", format: (v: any) => `R$ ${v.toLocaleString("pt-BR")}`, icon: DollarSign },
    { label: "Pre├ºo por Hectare", key: "preco_ha", format: (p: any) => p.area_total ? `R$ ${Math.round(p.price / p.area_total).toLocaleString("pt-BR")}` : "N/A" },
    { label: "├ügua", key: "agua", format: (v: any) => v ? "Ô£à Sim" : "ÔØî N├úo" },
    { label: "Energia El├®trica", key: "energia", format: (v: any) => v ? "Ô£à Sim" : "ÔØî N├úo" },
    { label: "Internet", key: "internet", format: (v: any) => v ? "Ô£à Sim" : "ÔØî N├úo" }
  ];

  return (
    <div className="min-h-screen bg-[#0a0a0a] pb-20">
      <div className="max-w-7xl mx-auto px-4 py-8">
        <Breadcrumbs />
        
        {/* Header */}
        <div className="flex items-center justify-between mb-8 flex-wrap gap-4">
          <div>
            <h1 className="text-3xl md:text-4xl font-bold text-transparent bg-clip-text bg-gradient-to-r from-[#E6C98B] to-[#A8C97F] mb-2">
              Comparar Propriedades
            </h1>
            <p className="text-[#8B9B6E]">
              Comparando {properties.length} {properties.length === 1 ? "propriedade" : "propriedades"}
            </p>
          </div>

          <div className="flex gap-3">
            <button
              onClick={shareComparison}
              className="flex items-center gap-2 px-4 py-2 border-2 border-[#E6C98B] text-[#E6C98B] font-semibold rounded-lg hover:bg-[#E6C98B]/10 transition-all"
              aria-label="Compartilhar compara├º├úo"
            >
              <Share2 className="w-5 h-5" />
              Compartilhar
            </button>
            <button
              onClick={downloadPDF}
              className="flex items-center gap-2 px-4 py-2 bg-gradient-to-r from-[#A8C97F] to-[#0D7377] text-[#0a0a0a] font-bold rounded-lg hover:scale-105 transition-all"
              aria-label="Baixar compara├º├úo em PDF"
            >
              <Download className="w-5 h-5" />
              Download PDF
            </button>
          </div>
        </div>

        {/* Comparison Table */}
        <div className="overflow-x-auto">
          <table className="w-full border-2 border-[#2a2a1a] rounded-2xl overflow-hidden">
            <thead>
              <tr className="bg-gradient-to-r from-[#1a1a1a] to-[#0d0d0d]">
                <th className="p-4 text-left text-[#8B9B6E] font-semibold border-b-2 border-[#2a2a1a] sticky left-0 bg-[#1a1a1a]">
                  Caracter├¡stica
                </th>
                {properties.map((property) => (
                  <th key={property.id} className="p-4 border-b-2 border-[#2a2a1a] min-w-[250px]">
                    <div className="relative">
                      <button
                        onClick={() => removeProperty(property.id)}
                        className="absolute -top-2 -right-2 p-1 bg-red-500/20 text-red-400 rounded-full hover:bg-red-500/30 transition-colors"
                        aria-label={`Remover ${property.title} da compara├º├úo`}
                      >
                        <X className="w-4 h-4" />
                      </button>
                      
                      <div className="w-full h-32 bg-[#2a2a1a] rounded-lg overflow-hidden mb-3">
                        {property.fotos && property.fotos[0] ? (
                          <Image
                            src={property.fotos[0]}
                            alt={property.title}
                            width={200}
                            height={128}
                            className="w-full h-full object-cover"
                            unoptimized
                          />
                        ) : (
                          <div className="w-full h-full flex items-center justify-center">
                            <MapPin className="w-8 h-8 text-[#959595]" />
                          </div>
                        )}
                      </div>
                      
                      <Link
                        href={`/imoveis/${property.id}`}
                        className="text-[#E6C98B] font-bold hover:text-[#A8C97F] transition-colors"
                      >
                        {property.title}
                      </Link>
                    </div>
                  </th>
                ))}
              </tr>
            </thead>
            <tbody>
              {comparisonRows.map((row, index) => {
                const Icon = row.icon;
                return (
                  <tr
                    key={row.key}
                    className={index % 2 === 0 ? "bg-[#0a0a0a]" : "bg-[#0d0d0d]"}
                  >
                    <td className="p-4 text-[#8B9B6E] font-semibold border-b border-[#2a2a1a] sticky left-0 bg-inherit">
                      <div className="flex items-center gap-2">
                        {Icon && <Icon className="w-4 h-4" />}
                        {row.label}
                      </div>
                    </td>
                    {properties.map((property) => (
                      <td key={property.id} className="p-4 text-[#E6C98B] border-b border-[#2a2a1a]">
                        {row.format
                          ? row.key === "preco_ha"
                            ? row.format(property)
                            : row.format((property as unknown as Record<string, any>)[row.key as string])
                          : row.key === "preco_ha"
                          ? "-"
                          : (property as unknown as Record<string, any>)[row.key as string]
                        }
                        {row.suffix && (property as unknown as Record<string, any>)[row.key as string] && row.suffix}
                      </td>
                    ))}
                  </tr>
                );
              })}
              
              {/* Description Row */}
              <tr className="bg-[#0a0a0a]">
                <td className="p-4 text-[#8B9B6E] font-semibold border-b border-[#2a2a1a] sticky left-0 bg-[#0a0a0a]">
                  Descri├º├úo
                </td>
                {properties.map((property) => (
                  <td key={property.id} className="p-4 text-[#676767] text-sm border-b border-[#2a2a1a]">
                    {property.description || "Sem descri├º├úo"}
                  </td>
                ))}
              </tr>

              {/* Action Row */}
              <tr className="bg-[#0d0d0d]">
                <td className="p-4 sticky left-0 bg-[#0d0d0d]"></td>
                {properties.map((property) => (
                  <td key={property.id} className="p-4">
                    <Link
                      href={`/imoveis/${property.id}`}
                      className="block w-full text-center px-4 py-3 bg-gradient-to-r from-[#A8C97F] to-[#0D7377] text-[#0a0a0a] font-bold rounded-lg hover:scale-105 transition-all"
                    >
                      Ver Detalhes
                    </Link>
                  </td>
                ))}
              </tr>
            </tbody>
          </table>
        </div>

        {/* Add More Properties */}
        {properties.length < 3 && (
          <div className="mt-8 text-center">
            <p className="text-[#8B9B6E] mb-4">
              Voc├¬ pode comparar at├® {3 - properties.length} {3 - properties.length === 1 ? "propriedade" : "propriedades"} adicionais
            </p>
            <Link
              href="/imoveis"
              className="inline-block px-6 py-3 border-2 border-[#E6C98B] text-[#E6C98B] font-semibold rounded-full hover:bg-[#E6C98B]/10 transition-all"
            >
              + Adicionar Propriedade
            </Link>
          </div>
        )}
      </div>
    </div>
  );
}

"use client";

import { useState, useEffect } from 'react';
import { useRouter } from 'next/navigation';
import { createClientComponentClient } from '@supabase/auth-helpers-nextjs';
import Link from 'next/link';
import { 
  User, LogOut, Heart, FileText, Calendar, Settings, 
  Home, TrendingUp, CheckCircle, Clock, XCircle 
} from 'lucide-react';

// Minimal local domain types to avoid wide `any` usage in the account page
type CurrentUser = { id: string; email?: string | null } | null;

type Property = {
  id: string;
  nome?: string;
  localizacao?: string;
  preco?: number | null;
};

type Proposal = {
  id: string;
  amount?: number;
  created_at?: string;
  status?: string;
  sitios?: { nome?: string } | null;
};

type Visit = {
  id: string;
  scheduled_date?: string;
  scheduled_time?: string;
  sitios?: { nome?: string } | null;
};

type Favorite = {
  id: string;
  sitios?: { id?: string; nome?: string; localizacao?: string; preco?: number } | null;
};

export default function ContaPage() {
  const router = useRouter();
  const supabase = createClientComponentClient();

  const [loading, setLoading] = useState(true);
  const [user, setUser] = useState<CurrentUser>(null);
  const [profile, setProfile] = useState<Record<string, any> | null>(null);
  const [activeTab, setActiveTab] = useState("overview");

  // Data
  const [properties, setProperties] = useState<Property[]>([]);
  const [proposals, setProposals] = useState<Proposal[]>([]);
  const [visits, setVisits] = useState<Visit[]>([]);
  const [favorites, setFavorites] = useState<Favorite[]>([]);

  useEffect(() => {
    void checkUser();
  }, []);

  const checkUser = async () => {
    try {
      const { data } = await supabase.auth.getUser();
      const currentUser = data?.user ?? null;

      if (!currentUser) {
        router.push("/entrar?redirect=/conta");
        return;
      }

      setUser({ id: currentUser.id, email: currentUser.email ?? null });

      // Fetch profile
      const { data: profileData } = await supabase
        .from("user_profiles")
        .select("*")
        .eq("id", currentUser.id)
        .single();

      setProfile(profileData);

      // Fetch user-related data in parallel

      const [propsRes, proposalsRes, visitsRes, favsRes] = await Promise.all([
        supabase.from("properties").select("*").eq("user_id", currentUser.id),
        supabase.from("proposals").select("*").eq("user_id", currentUser.id),
        supabase.from("visits").select("*").eq("user_id", currentUser.id),
        supabase
          .from("property_favorites")
          .select("*, sitios(*)")
          .eq("user_id", currentUser.id),
      ]);

      setProperties((propsRes.data ?? []) as Property[]);
      setProposals((proposalsRes.data ?? []) as Proposal[]);
      setVisits((visitsRes.data ?? []) as Visit[]);
      setFavorites((favsRes.data ?? []) as Favorite[]);

      setLoading(false);
    } catch (err) {
      console.error("Error checking user", err);
      router.push("/entrar?redirect=/conta");
    }
  };

  return (
    <main className="min-h-screen bg-[#0a0a0a] py-12">
      <div className="max-w-6xl mx-auto px-6">
        <div className="flex items-center justify-between mb-8">
          <h1 className="text-3xl font-bold text-[#D4A574]">Minha Conta</h1>
        </div>

        <nav className="mb-8">
          <div className="flex gap-3">
            <button
              onClick={() => setActiveTab("overview")}
              className={`px-4 py-2 rounded ${activeTab === "overview" ? "bg-[#A8C97F] text-black font-bold" : "bg-[#1a1a1a] text-[#D4A574]"}`}
            >
              Vis├úo Geral
            </button>
            <button
              onClick={() => setActiveTab("properties")}
              className={`px-4 py-2 rounded ${activeTab === "properties" ? "bg-[#A8C97F] text-black font-bold" : "bg-[#1a1a1a] text-[#D4A574]"}`}
            >
              Minhas Propriedades
            </button>
            <button
              onClick={() => setActiveTab("proposals")}
              className={`px-4 py-2 rounded ${activeTab === "proposals" ? "bg-[#A8C97F] text-black font-bold" : "bg-[#1a1a1a] text-[#D4A574]"}`}
            >
              Minhas Propostas
            </button>
            <button
              onClick={() => setActiveTab("visits")}
              className={`px-4 py-2 rounded ${activeTab === "visits" ? "bg-[#A8C97F] text-black font-bold" : "bg-[#1a1a1a] text-[#D4A574]"}`}
            >
              Minhas Visitas
            </button>
            <button
              onClick={() => setActiveTab("favorites")}
              className={`px-4 py-2 rounded ${activeTab === "favorites" ? "bg-[#A8C97F] text-black font-bold" : "bg-[#1a1a1a] text-[#D4A574]"}`}
            >
              Favoritos
            </button>
          </div>
        </nav>

        <section>
          {loading ? (
            <div className="text-center py-20 text-[#676767]">Carregando...</div>
          ) : (
            <div>
              {activeTab === "overview" && (
                <div className="space-y-6">
                  <h2 className="text-2xl font-bold text-[#D4A574]">Bem-vindo de volta!</h2>
                  <p className="text-[#676767]">Aqui est├í um resumo da sua atividade na plataforma.</p>

                  <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    <Link href="/postar" className="p-6 bg-gradient-to-br from-[#A8C97F]/20 to-[#0D7377]/20 border border-[#A8C97F]/50 rounded-xl hover:scale-105 transition">
                      <Home className="w-12 h-12 text-[#A8C97F] mb-4" />
                      <h3 className="text-xl font-bold text-[#A8C97F] mb-2">Anunciar Propriedade</h3>
                      <p className="text-[#676767] text-sm">Publique sua propriedade gratuitamente</p>
                    </Link>

                    <Link href="/favoritos" className="p-6 bg-gradient-to-br from-[#E6C98B]/20 to-[#B87333]/20 border border-[#E6C98B]/50 rounded-xl hover:scale-105 transition">
                      <Heart className="w-12 h-12 text-[#E6C98B] mb-4" />
                      <h3 className="text-xl font-bold text-[#E6C98B] mb-2">Minhas Propriedades Favoritas</h3>
                      <p className="text-[#676767] text-sm">{favorites.length} propriedades salvas</p>
                    </Link>
                  </div>
                </div>
              )}

              {activeTab === "properties" && (
                <div>
                  <h2 className="text-2xl font-bold text-[#D4A574] mb-6">Minhas Propriedades</h2>
                  {properties.length === 0 ? (
                    <div className="text-center py-12">
                      <Home className="w-16 h-16 text-[#676767] mx-auto mb-4" />
                      <p className="text-[#676767] mb-4">Voc├¬ ainda n├úo anunciou nenhuma propriedade</p>
                      <Link href="/postar" className="inline-block px-6 py-3 bg-gradient-to-r from-[#A8C97F] to-[#0D7377] text-white font-bold rounded-lg hover:scale-105 transition">Anunciar Agora</Link>
                    </div>
                  ) : (
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                      {properties.map((prop) => (
                        <div key={prop.id} className="bg-[#1a1a1a] border border-[#3a3a3a] rounded-lg p-4">
                          <h3 className="text-[#D4A574] font-bold mb-2">{prop.nome}</h3>
                          <p className="text-[#676767] text-sm">{prop.localizacao}</p>
                          <p className="text-[#A8C97F] font-bold mt-2">R$ {prop.preco?.toLocaleString('pt-BR')}</p>
                        </div>
                      ))}
                    </div>
                  )}
                </div>
              )}

              {activeTab === "proposals" && (
                <div>
                  <h2 className="text-2xl font-bold text-[#D4A574] mb-6">Minhas Propostas</h2>
                  {proposals.length === 0 ? (
                    <div className="text-center py-12">
                      <TrendingUp className="w-16 h-16 text-[#676767] mx-auto mb-4" />
                      <p className="text-[#676767]">Voc├¬ ainda n├úo fez nenhuma proposta</p>
                    </div>
                  ) : (
                    <div className="space-y-4">
                      {proposals.map((prop) => (
                        <div key={prop.id} className="bg-[#1a1a1a] border border-[#3a3a3a] rounded-lg p-4 flex items-center justify-between">
                          <div>
                            <h3 className="text-[#D4A574] font-bold">{prop.sitios?.nome}</h3>
                            <p className="text-[#A8C97F] font-bold">R$ {prop.amount?.toLocaleString('pt-BR')}</p>
                            <p className="text-[#676767] text-sm">{new Date(prop.created_at).toLocaleDateString('pt-BR')}</p>
                          </div>
                          <div className="flex items-center gap-2">
                            {prop.status === 'pending' && (
                              <>
                                <Clock className="w-5 h-5 text-yellow-500" />
                                <span className="text-yellow-500 text-sm">Pendente</span>
                              </>
                            )}
                            {prop.status === 'accepted' && (
                              <>
                                <CheckCircle className="w-5 h-5 text-green-500" />
                                <span className="text-green-500 text-sm">Aceita</span>
                              </>
                            )}
                            {prop.status === 'rejected' && (
                              <>
                                <XCircle className="w-5 h-5 text-red-500" />
                                <span className="text-red-500 text-sm">Recusada</span>
                              </>
                            )}
                          </div>
                        </div>
                      ))}
                    </div>
                  )}
                </div>
              )}

              {activeTab === "visits" && (
                <div>
                  <h2 className="text-2xl font-bold text-[#D4A574] mb-6">Minhas Visitas</h2>
                  {visits.length === 0 ? (
                    <div className="text-center py-12">
                      <Calendar className="w-16 h-16 text-[#676767] mx-auto mb-4" />
                      <p className="text-[#676767]">Voc├¬ ainda n├úo agendou nenhuma visita</p>
                    </div>
                  ) : (
                    <div className="space-y-4">
                      {visits.map((visit) => (
                        <div key={visit.id} className="bg-[#1a1a1a] border border-[#3a3a3a] rounded-lg p-4">
                          <h3 className="text-[#D4A574] font-bold">{visit.sitios?.nome}</h3>
                          <p className="text-[#676767] text-sm">{new Date(visit.scheduled_date).toLocaleDateString('pt-BR')} ├ás {visit.scheduled_time}</p>
                        </div>
                      ))}
                    </div>
                  )}
                </div>
              )}

              {activeTab === "favorites" && (
                <div>
                  <h2 className="text-2xl font-bold text-[#D4A574] mb-6">Propriedades que Gostei</h2>
                  {favorites.length === 0 ? (
                    <div className="text-center py-12">
                      <Heart className="w-16 h-16 text-[#676767] mx-auto mb-4" />
                      <p className="text-[#676767] mb-4">Voc├¬ ainda n├úo salvou nenhuma propriedade</p>
                      <Link href="/" className="inline-block px-6 py-3 bg-gradient-to-r from-[#E6C98B] to-[#B87333] text-[#0a0a0a] font-bold rounded-lg hover:scale-105 transition">Explorar Propriedades</Link>
                    </div>
                  ) : (
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                      {favorites.map((fav) => (
                        <Link key={fav.id} href={`/imoveis/${fav.sitios?.id}`} className="bg-[#1a1a1a] border border-[#3a3a3a] rounded-lg p-4 hover:border-[#A8C97F] transition">
                          <h3 className="text-[#D4A574] font-bold mb-2">{fav.sitios?.nome}</h3>
                          <p className="text-[#676767] text-sm">{fav.sitios?.localizacao}</p>
                          <p className="text-[#A8C97F] font-bold mt-2">R$ {fav.sitios?.preco?.toLocaleString('pt-BR')}</p>
                        </Link>
                      ))}
                    </div>
                  )}
                </div>
              )}
            </div>
          )}
        </section>
      </div>
    </main>
  );
}

"use client";

import { useState, FormEvent } from "react";
import Image from "next/image";
import Link from "next/link";
import { supabase } from "@/lib/supabaseClient";
import { ArrowLeft, Mail, Phone, MessageSquare, CheckCircle, AlertCircle } from "lucide-react";
import { WhatsAppLink } from "@publimicro/ui";

export default function ContatoPage() {
  const [formData, setFormData] = useState({
    nome: "",
    email: "",
    telefone: "",
    mensagem: "",
  });
  const [submitting, setSubmitting] = useState(false);
  const [success, setSuccess] = useState(false);
  const [error, setError] = useState("");

  const handleSubmit = async (e: FormEvent) => {
    e.preventDefault();
    setSubmitting(true);
    setError("");
    setSuccess(false);

    try {
      const { error: submitError } = await supabase
        .from("contacts")
        .insert({
          nome: formData.nome,
          email: formData.email,
          telefone: formData.telefone || null,
          mensagem: formData.mensagem,
          status: "novo",
        });

      if (submitError) throw submitError;

      setSuccess(true);
      setFormData({
        nome: "",
        email: "",
        telefone: "",
        mensagem: "",
      });

      // Auto-hide success message after 5 seconds
      setTimeout(() => setSuccess(false), 5000);
    } catch (err: any) {
      console.error("Error submitting contact form:", err);
      setError(err.message || "Erro ao enviar mensagem. Tente novamente.");
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <main className="relative min-h-screen">
      {/* Imagem de fundo */}
      <div className="absolute inset-0 -z-10">
        <Image
          src="https://irrzpwzyqcubhhjeuakc.supabase.co/storage/v1/object/public/imagens-sitios/sitioCanarioFogueira.jpg"
          alt="Fundo contato"
          fill
          className="object-cover brightness-75"
          priority
        />
      </div>

      {/* Back Button */}
      <div className="absolute top-6 left-6 z-20">
        <Link
          href="/"
          className="flex items-center gap-2 px-4 py-2 bg-black/60 hover:bg-black/80 text-[#E6C98B] border border-[#E6C98B]/30 rounded-full transition-all backdrop-blur-sm"
        >
          <ArrowLeft className="w-5 h-5" />
          <span>Voltar</span>
        </Link>
      </div>

      {/* Conte├║do */}
      <section className="flex flex-col items-center justify-center min-h-screen text-[#E6C98B] text-center px-6 py-20">
        <div className="bg-black/70 backdrop-blur-sm p-10 rounded-2xl max-w-2xl w-full shadow-2xl border border-[#E6C98B]/20">
          <h1 className="text-4xl font-bold mb-3 text-transparent bg-clip-text bg-gradient-to-r from-[#E6C98B] to-[#A8C97F]">
            Contato & Agendamento
          </h1>
          <p className="mb-8 text-lg text-[#8B9B6E]">
            Solicite informa├º├Áes, agende visitas presenciais ou videoconfer├¬ncias.
          </p>

          {/* Success Message */}
          {success && (
            <div className="mb-6 p-4 bg-green-900/30 border border-green-500/50 rounded-lg flex items-center gap-3 animate-pulse">
              <CheckCircle className="w-6 h-6 text-green-400 flex-shrink-0" />
              <div className="text-left">
                <p className="text-green-400 font-semibold">Mensagem enviada com sucesso!</p>
                <p className="text-green-300 text-sm">Entraremos em contato em breve.</p>
              </div>
            </div>
          )}

          {/* Error Message */}
          {error && (
            <div className="mb-6 p-4 bg-red-900/30 border border-red-500/50 rounded-lg flex items-center gap-3">
              <AlertCircle className="w-6 h-6 text-red-400 flex-shrink-0" />
              <p className="text-red-400 text-left">{error}</p>
            </div>
          )}

          <form onSubmit={handleSubmit} className="flex flex-col gap-4">
            {/* Nome */}
            <div>
              <label htmlFor="nome" className="sr-only">Nome completo</label>
              <input
                id="nome"
                type="text"
                placeholder="Nome completo *"
                value={formData.nome}
                onChange={(e) => setFormData({ ...formData, nome: e.target.value })}
                required
                className="w-full p-4 rounded-lg bg-[#0a0a0a]/80 border-2 border-[#2a2a1a] text-[#E6C98B] placeholder-[#676767] focus:border-[#A8C97F] focus:outline-none transition-colors"
              />
            </div>

            {/* Email */}
            <div>
              <label htmlFor="email" className="sr-only">Email</label>
              <div className="relative">
                <Mail className="absolute left-4 top-1/2 -translate-y-1/2 w-5 h-5 text-[#676767]" />
                <input
                  id="email"
                  type="email"
                  placeholder="Email *"
                  value={formData.email}
                  onChange={(e) => setFormData({ ...formData, email: e.target.value })}
                  required
                  className="w-full pl-12 pr-4 py-4 rounded-lg bg-[#0a0a0a]/80 border-2 border-[#2a2a1a] text-[#E6C98B] placeholder-[#676767] focus:border-[#A8C97F] focus:outline-none transition-colors"
                />
              </div>
            </div>

            {/* Telefone */}
            <div>
              <label htmlFor="telefone" className="sr-only">Telefone ou WhatsApp</label>
              <div className="relative">
                <Phone className="absolute left-4 top-1/2 -translate-y-1/2 w-5 h-5 text-[#676767]" />
                <input
                  id="telefone"
                  type="text"
                  placeholder="Telefone/WhatsApp"
                  value={formData.telefone}
                  onChange={(e) => setFormData({ ...formData, telefone: e.target.value })}
                  className="w-full pl-12 pr-4 py-4 rounded-lg bg-[#0a0a0a]/80 border-2 border-[#2a2a1a] text-[#E6C98B] placeholder-[#676767] focus:border-[#A8C97F] focus:outline-none transition-colors"
                />
              </div>
            </div>

            {/* Mensagem */}
            <div>
              <label htmlFor="mensagem" className="sr-only">Mensagem</label>
              <div className="relative">
                <MessageSquare className="absolute left-4 top-4 w-5 h-5 text-[#676767]" />
                <textarea
                  id="mensagem"
                  placeholder="Mensagem *"
                  value={formData.mensagem}
