                    previouslyFocusedElement.current.focus();
                  }
                }}
              />
            </div>
          </FocusLock>
        </div>
      )}

      {/* Proposal Modal */}
      {proposalModalOpen && (
        <ProposalModal
          adId={sitio.id}
          adTitle={sitio.nome}
          currentBid={currentHighestBid || sitio.preco || sitio.lance_inicial || 0}
          minBid={sitio.preco || sitio.lance_inicial || 0}
