"use client";

import { useState, useEffect } from "react";
import SearchTab, { SearchFilters } from "@/components/SearchTab";
import { supabase } from "@/lib/supabaseClient";
import Link from "next/link";
import Image from "next/image";
import { MapPin, Maximize2, DollarSign, Heart, Filter, Grid3x3, List, Scale } from "lucide-react";
import Breadcrumbs from "@/components/Breadcrumbs";
import { Skeleton } from "@/components/Skeleton";
import { addToComparison, isInComparison } from "@/lib/comparison";
import { useToast } from "@/components/ToastNotification";

interface Property {
  id: string;
  title: string;
  location: string;
  price: number;
  area_total: number;
  fotos: string[];
  description: string;
  created_at: string;
  highest_bid?: number;
  bid_count?: number;
}

export default function ImoveisPage() {
  const [properties, setProperties] = useState<Property[]>([]);
  const [loading, setLoading] = useState(true);
  const [viewMode, setViewMode] = useState<"grid" | "list">("grid");
  const { showToast } = useToast();
  const [filters, setFilters] = useState<SearchFilters>({
    query: "",
    priceMin: 0,
    priceMax: 10000000,
    areaMin: 0,
    areaMax: 1000,
    location: "",
    sortBy: "relevance",
    searchType: "properties",
  });
  const [totalResults, setTotalResults] = useState(0);

  useEffect(() => {
    void loadProperties();
  }, [filters]);

  const loadProperties = async () => {
    setLoading(true);

    try {
      let queryBuilder = supabase
        .from("properties")
        .select("id, title, location, price, area_total, fotos, description, created_at", {
          count: "exact",
        });

      // Text search
      if (filters.query) {
        queryBuilder = queryBuilder.or(
          `title.ilike.%${filters.query}%,location.ilike.%${filters.query}%,description.ilike.%${filters.query}%`
        );
      }

      // Price filter
      if (Number(filters.priceMin) > 0) {
        queryBuilder = queryBuilder.gte("price", Number(filters.priceMin));
      }
      if (Number(filters.priceMax) < 10000000) {
        queryBuilder = queryBuilder.lte("price", Number(filters.priceMax));
      }

      // Area filter
      if (Number(filters.areaMin) > 0) {
        queryBuilder = queryBuilder.gte("area_total", Number(filters.areaMin));
      }
      if (Number(filters.areaMax) < 1000) {
        queryBuilder = queryBuilder.lte("area_total", Number(filters.areaMax));
      }

      // Location filter
      if (filters.location) {
        queryBuilder = queryBuilder.ilike("location", `%${filters.location}%`);
      }

      // Sorting
      switch (filters.sortBy) {
        case "price_asc":
          queryBuilder = queryBuilder.order("price", { ascending: true });
          break;
        case "price_desc":
          queryBuilder = queryBuilder.order("price", { ascending: false });
          break;
        case "area_desc":
          queryBuilder = queryBuilder.order("area_total", { ascending: false });
          break;
        case "newest":
          queryBuilder = queryBuilder.order("created_at", { ascending: false });
          break;
        default:
          queryBuilder = queryBuilder.order("created_at", { ascending: false });
          break;
      }

      const { data, error, count } = await queryBuilder;

      if (error) throw error;

      // Fetch highest bids for all properties
      const propertiesWithBids = await Promise.all(
        (data || []).map(async (property) => {
          const { data: bidsData } = await supabase
            .from("proposals")
            .select("bid_amount")
            .eq("property_id", property.id)
            .neq("status", "rejected")
            .order("bid_amount", { ascending: false })
            .limit(1);

          const { count: bidCount } = await supabase
            .from("proposals")
            .select("*", { count: "exact", head: true })
            .eq("property_id", property.id)
            .neq("status", "rejected");

          return {
            ...property,
            highest_bid: bidsData && bidsData.length > 0 ? bidsData[0].bid_amount : null,
            bid_count: bidCount || 0,
          };
        })
      );

      setProperties(propertiesWithBids);
      setTotalResults(count || 0);
    } catch (error) {
      console.error("Error loading properties:", error);
      setProperties([]);
      setTotalResults(0);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-[#0a0a0a]">
      {/* Hero Section with Search */}
      <div className="bg-gradient-to-b from-[#1a1a1a] to-[#0a0a0a] border-b-2 border-[#2a2a1a]">
        <div className="max-w-7xl mx-auto px-4 py-8">
          <Breadcrumbs />
          
          <div className="text-center mb-8 mt-4">
            <h1 className="text-4xl md:text-5xl font-bold text-transparent bg-clip-text bg-gradient-to-r from-[#E6C98B] to-[#A8C97F] mb-4">
              Todas as Propriedades
            </h1>
            <p className="text-[#8B9B6E] text-lg">
              Explore nosso cat├ílogo completo de propriedades rurais e urbanas
            </p>
          </div>
          
          <SearchTab onFilterChange={setFilters} />
          
          {/* Results Summary */}
          <div className="mt-6 flex items-center justify-between flex-wrap gap-4">
            <p className="text-[#8B9B6E]">
              {loading ? (
                "Carregando..."
              ) : (
                <>
                  <span className="font-bold text-[#A8C97F]">{totalResults}</span>{" "}
                  {totalResults === 1 ? "propriedade encontrada" : "propriedades encontradas"}
                  {filters.query && (
                    <>
                      {" "}para "<span className="text-[#E6C98B]">{filters.query}</span>"
                    </>
                  )}
                </>
              )}
            </p>

            {/* View Mode Toggle */}
            <div className="flex items-center gap-2 bg-[#1a1a1a] border border-[#2a2a1a] rounded-lg p-1">
              <button
                onClick={() => setViewMode("grid")}
                className={`p-2 rounded transition-all ${
                  viewMode === "grid"
                    ? "bg-gradient-to-r from-[#A8C97F] to-[#0D7377] text-[#0a0a0a]"
                    : "text-[#8B9B6E] hover:bg-[#2a2a1a]"
                }`}
              >
                <Grid3x3 className="w-5 h-5" />
              </button>
              <button
                onClick={() => setViewMode("list")}
                className={`p-2 rounded transition-all ${
                  viewMode === "list"
                    ? "bg-gradient-to-r from-[#A8C97F] to-[#0D7377] text-[#0a0a0a]"
                    : "text-[#8B9B6E] hover:bg-[#2a2a1a]"
                }`}
              >
                <List className="w-5 h-5" />
              </button>
            </div>
          </div>
        </div>
      </div>

      {/* Results */}
      <div className="max-w-7xl mx-auto px-4 py-8">
        {loading ? (
          <div className={viewMode === "grid" ? "grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6" : "space-y-4"}>
            {[...Array(6)].map((_, i) => (
              <Skeleton key={i} variant="card" width="100%" height={viewMode === "grid" ? "400px" : "200px"} />
            ))}
          </div>
        ) : properties.length > 0 ? (
          <div className={viewMode === "grid" ? "grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6" : "space-y-4"}>
            {properties.map((property) => (
              <Link
                key={property.id}
                href={`/imoveis/${property.id}`}
                className={`bg-gradient-to-br from-[#1a1a1a] to-[#0d0d0d] border-2 border-[#2a2a1a] rounded-2xl overflow-hidden hover:border-[#A8C97F] transition-all hover:scale-105 shadow-lg hover:shadow-2xl group ${
                  viewMode === "list" ? "flex" : ""
                }`}
              >
                {/* Image */}
                <div className={`relative bg-[#2a2a1a] overflow-hidden ${viewMode === "grid" ? "w-full h-64" : "w-64 h-48 flex-shrink-0"}`}>
                  {property.fotos && property.fotos[0] ? (
                    <Image
                      src={property.fotos[0]}
                      alt={property.title}
                      fill
                      sizes="(max-width: 768px) 100vw, (max-width: 1200px) 50vw, 33vw"
                      className="object-cover group-hover:scale-110 transition-transform duration-300"
                      unoptimized
                    />
                  ) : (
                    <div className="w-full h-full flex items-center justify-center">
                      <MapPin className="w-16 h-16 text-[#676767]" />
                    </div>
                  )}
                  
                  {/* Favorite Button */}
                  <button
                    onClick={(e) => {
                      e.preventDefault();
                      // Handle favorite toggle
                    }}
                    className="absolute top-4 right-4 p-2 bg-[#0a0a0a]/80 hover:bg-[#A8C97F] rounded-full transition-all group/fav"
                    aria-label="Adicionar aos favoritos"
                  >
                    <Heart className="w-5 h-5 text-[#E6C98B] group-hover/fav:fill-current" />
                  </button>
                  
                  {/* Comparison Button */}
                  <button
                    onClick={(e) => {
                      e.preventDefault();
                      e.stopPropagation();
                      const added = addToComparison(property.id);
                      if (added) {
                        showToast({
                          type: "success",
                          title: "Adicionado ├á compara├º├úo",
                          message: `${property.title} foi adicionado. V├í para Comparar.`
                        });
                      }
                    }}
                    className={`absolute top-4 left-4 p-2 rounded-full transition-all ${
                      isInComparison(property.id)
                        ? "bg-[#A8C97F] text-[#0a0a0a]"
                        : "bg-[#0a0a0a]/80 hover:bg-[#E6C98B] text-[#E6C98B]"
                    }`}
                    aria-label={isInComparison(property.id) ? "Remover da compara├º├úo" : "Adicionar ├á compara├º├úo"}
                  >
                    <Scale className="w-5 h-5" />
                  </button>
                </div>

                {/* Content */}
                <div className="p-6 flex-1">
                  <h3 className="text-xl font-bold text-[#E6C98B] mb-3 group-hover:text-[#A8C97F] transition-colors">
                    {property.title}
                  </h3>

                  <div className="space-y-2 mb-4">
                    <div className="flex items-center gap-2 text-[#8B9B6E]">
                      <MapPin className="w-4 h-4" />
                      <span className="text-sm">{property.location}</span>
                    </div>

                    {property.area_total && (
                      <div className="flex items-center gap-2 text-[#8B9B6E]">
                        <Maximize2 className="w-4 h-4" />
                        <span className="text-sm">{property.area_total} hectares</span>
                      </div>
                    )}
                  </div>

                  {/* Price */}
                  <div className={viewMode === "list" ? "mb-4" : ""}>
                    {property.price ? (
                      <div>
                        <div className="flex items-center gap-2">
                          <DollarSign className="w-5 h-5 text-[#A8C97F]" />
                          <span className="text-2xl font-bold text-[#A8C97F]">
                            R$ {property.price.toLocaleString("pt-BR")}
                          </span>
                        </div>
                        
                        {/* Highest Bid Display */}
                        {property.highest_bid && property.highest_bid > 0 && (
                          <div className="mt-2 flex items-center gap-2">
                            {property.highest_bid > property.price && (
                              <span className="text-lg">­ƒöÑ</span>
                            )}
                            <div className="bg-[#A8C97F]/20 border border-[#A8C97F]/40 rounded-lg px-3 py-1">
                              <p className="text-xs text-[#E6C98B]">Lance mais alto:</p>
                              <p className="text-sm font-bold text-[#A8C97F]">
                                R$ {property.highest_bid.toLocaleString("pt-BR")}
                              </p>
                            </div>
                            {property.bid_count && property.bid_count > 1 && (
                              <span className="text-xs text-[#8B9B6E]">
                                ({property.bid_count} lances)
                              </span>
                            )}
                          </div>
                        )}
                        
                        {!property.highest_bid && (
                          <p className="text-xs text-[#676767] mt-2">Sem lances ainda</p>
                        )}
                      </div>
                    ) : (
                      <span className="text-[#8B9B6E] text-sm">Consultar pre├ºo</span>
                    )}
                  </div>

                  {/* Description Preview */}
                  {property.description && viewMode === "list" && (
                    <p className="text-sm text-[#676767] line-clamp-2">
                      {property.description}
                    </p>
                  )}
                </div>
              </Link>
            ))}
          </div>
        ) : (
          <div className="text-center py-20">
            <div className="w-32 h-32 mx-auto mb-6 bg-[#2a2a1a] rounded-full flex items-center justify-center">
              <MapPin className="w-16 h-16 text-[#676767]" />
            </div>
            <h2 className="text-2xl font-bold text-[#E6C98B] mb-3">
              Nenhuma propriedade encontrada
            </h2>
            <p className="text-[#8B9B6E] mb-6">
              Tente ajustar os filtros ou fazer uma nova busca
            </p>
            <button
              onClick={() => {
                setFilters({
                  query: "",
                  priceMin: 0,
                  priceMax: 10000000,
                  areaMin: 0,
                  areaMax: 1000,
                  location: "",
                  sortBy: "relevance",
                  searchType: "properties",
                });
              }}
              className="px-6 py-3 bg-gradient-to-r from-[#A8C97F] to-[#0D7377] text-[#0a0a0a] font-bold rounded-full hover:scale-105 transition-all"
            >
              Limpar Filtros
            </button>
          </div>
        )}
      </div>
    </div>
  );
}

"use client";

import { useState, useEffect } from "react";
import { supabase } from "@/lib/supabaseClient";
import Link from "next/link";
import Image from "next/image";
import { TrendingUp, Clock, CheckCircle, XCircle, AlertCircle, Eye, DollarSign, Calendar } from "lucide-react";
import Breadcrumbs from "@/components/Breadcrumbs";
import { Skeleton } from "@/components/Skeleton";

interface Bid {
  id: string;
  property_id: string;
  bid_amount: number;
  message: string;
  status: "pending" | "accepted" | "rejected" | "counter";
  created_at: string;
  updated_at: string;
  properties: {
    title: string;
    location: string;
    price: number;
    fotos: string[];
  } | null;
  highest_bid?: number;
  competing_bids?: number;
}

export default function LancesPage() {
  const [bids, setBids] = useState<Bid[]>([]);
  const [loading, setLoading] = useState(true);
  const [filter, setFilter] = useState<"all" | "pending" | "accepted" | "rejected">("all");
  const [userId, setUserId] = useState<string | null>(null);

  useEffect(() => {
    void loadUserAndBids();
  }, [filter]);

  const loadUserAndBids = async () => {
    try {
      const { data: { user } } = await supabase.auth.getUser();
      
      if (!user) {
        window.location.href = "/entrar";
        return;
      }

      setUserId(user.id);
      await loadBids(user.id);
    } catch (error) {
      console.error("Error loading user:", error);
    }
  };

  const loadBids = async (userId: string) => {
    setLoading(true);
    try {
      let query = supabase
        .from("proposals")
        .select(`
          *,
          properties (
            title,
            location,
            price,
            fotos
          )
        `)
        .eq("user_id", userId)
        .order("created_at", { ascending: false });

      if (filter !== "all") {
        query = query.eq("status", filter);
      }

      const { data, error } = await query;

      if (error) throw error;

      // Load competing bids count and highest bid for each property
      const bidsWithStats = await Promise.all(
        (data || []).map(async (bid) => {
          const { count } = await supabase
            .from("proposals")
            .select("*", { count: "exact", head: true })
            .eq("property_id", bid.property_id)
            .neq("status", "rejected");

          const { data: highestBidData } = await supabase
            .from("proposals")
            .select("bid_amount")
            .eq("property_id", bid.property_id)
            .neq("status", "rejected")
            .order("bid_amount", { ascending: false })
            .limit(1)
            .single();

          return {
            ...bid,
            competing_bids: (count || 1) - 1, // Subtract own bid
            highest_bid: highestBidData?.bid_amount || bid.bid_amount
          };
        })
      );

      setBids(bidsWithStats);
    } catch (error) {
      console.error("Error loading bids:", error);
    } finally {
      setLoading(false);
    }
  };

  const getStatusIcon = (status: string) => {
    switch (status) {
      case "pending":
        return <Clock className="w-5 h-5 text-[#B7791F]" />;
      case "accepted":
        return <CheckCircle className="w-5 h-5 text-[#8B9B6E]" />;
      case "rejected":
        return <XCircle className="w-5 h-5 text-red-400" />;
      case "counter":
        return <AlertCircle className="w-5 h-5 text-[#6A1B9A]" />;
      default:
        return <Clock className="w-5 h-5 text-[#676767]" />;
    }
  };

  const getStatusLabel = (status: string) => {
    const labels = {
      pending: "Aguardando",
      accepted: "Aceito",
      rejected: "Recusado",
      counter: "Contraproposta"
    };
    return labels[status as keyof typeof labels] || status;
  };

  const getStatusColor = (status: string) => {
    const colors = {
      pending: "bg-[#B7791F]/20 text-[#B7791F] border-[#B7791F]",
      accepted: "bg-[#A8C97F]/20 text-[#A8C97F] border-[#A8C97F]",
      rejected: "bg-red-500/20 text-red-400 border-red-500",
      counter: "bg-[#6A1B9A]/20 text-[#6A1B9A] border-[#6A1B9A]"
    };
    return colors[status as keyof typeof colors] || "bg-[#2a2a1a] text-[#676767] border-[#676767]";
  };

  const stats = {
    total: bids.length,
    pending: bids.filter(b => b.status === "pending").length,
    accepted: bids.filter(b => b.status === "accepted").length,
    rejected: bids.filter(b => b.status === "rejected").length,
    totalAmount: bids.reduce((sum, bid) => sum + bid.bid_amount, 0)
  };

  return (
    <div className="min-h-screen bg-[#0a0a0a] pb-20">
      <div className="max-w-7xl mx-auto px-4 py-8">
        <Breadcrumbs />

        {/* Header */}
        <div className="mb-8">
          <h1 className="text-3xl md:text-4xl font-bold text-transparent bg-clip-text bg-gradient-to-r from-[#E6C98B] to-[#B7791F] mb-2">
            Meus Lances
          </h1>
          <p className="text-[#8B9B6E]">
            Acompanhe todos os seus lances em propriedades
          </p>
        </div>

        {/* Stats Cards */}
        <div className="grid grid-cols-2 md:grid-cols-5 gap-4 mb-8">
          <div className="bg-gradient-to-br from-[#1a1a1a] to-[#0d0d0d] border-2 border-[#2a2a1a] rounded-xl p-4">
            <p className="text-[#A8C97F] text-sm mb-1">Total de Lances</p>
            <p className="text-2xl font-bold text-[#E6C98B]">{stats.total}</p>
          </div>
          
          <div className="bg-gradient-to-br from-[#1a1a1a] to-[#0d0d0d] border-2 border-[#B7791F]/30 rounded-xl p-4">
            <p className="text-[#A8C97F] text-sm mb-1">Aguardando</p>
            <p className="text-2xl font-bold text-[#B7791F]">{stats.pending}</p>
          </div>
          
          <div className="bg-gradient-to-br from-[#1a1a1a] to-[#0d0d0d] border-2 border-[#A8C97F]/30 rounded-xl p-4">
            <p className="text-[#A8C97F] text-sm mb-1">Aceitos</p>
            <p className="text-2xl font-bold text-[#A8C97F]">{stats.accepted}</p>
          </div>
          
          <div className="bg-gradient-to-br from-[#1a1a1a] to-[#0d0d0d] border-2 border-red-500/30 rounded-xl p-4">
            <p className="text-[#A8C97F] text-sm mb-1">Recusados</p>
            <p className="text-2xl font-bold text-red-400">{stats.rejected}</p>
          </div>
          
          <div className="bg-gradient-to-br from-[#1a1a1a] to-[#0d0d0d] border-2 border-[#0D7377]/30 rounded-xl p-4">
            <p className="text-[#A8C97F] text-sm mb-1">Valor Total</p>
            <p className="text-lg font-bold text-[#0D7377]">R$ {stats.totalAmount.toLocaleString("pt-BR")}</p>
          </div>
        </div>

        {/* Filters */}
        <div className="flex gap-3 mb-6 overflow-x-auto pb-2">
          {[
            { value: "all", label: "Todos" },
            { value: "pending", label: "Aguardando" },
            { value: "accepted", label: "Aceitos" },
            { value: "rejected", label: "Recusados" }
          ].map((filterOption) => (
            <button
              key={filterOption.value}
              onClick={() => setFilter(filterOption.value as "all" | "pending" | "accepted" | "rejected")}
              className={`px-6 py-2 rounded-full font-semibold transition-all whitespace-nowrap ${
                filter === filterOption.value
                  ? "bg-gradient-to-r from-[#A8C97F] to-[#0D7377] text-white"
                  : "bg-[#2a2a1a] text-[#A8C97F] hover:bg-[#3a3a2a]"
              }`}
            >
              {filterOption.label}
            </button>
          ))}
        </div>

        {/* Bids List */}
        {loading ? (
          <div className="space-y-4">
            {[...Array(3)].map((_, i) => (
              <Skeleton key={i} variant="card" className="w-full h-48" />
            ))}
          </div>
        ) : bids.length > 0 ? (
          <div className="space-y-4">
            {bids.map((bid) => (
              <div
                key={bid.id}
                className="bg-gradient-to-br from-[#1a1a1a] to-[#0d0d0d] border-2 border-[#2a2a1a] rounded-2xl overflow-hidden hover:border-[#A8C97F] transition-all"
              >
                <div className="p-6">
                  <div className="flex flex-col md:flex-row gap-6">
                    {/* Property Image */}
                    <div className="w-full md:w-48 h-32 bg-[#2a2a1a] rounded-lg overflow-hidden flex-shrink-0">
                      {bid.properties?.fotos && bid.properties.fotos[0] ? (
                        <Image
                          src={bid.properties.fotos[0]}
                          alt={bid.properties.title || "Propriedade"}
                          width={192}
                          height={128}
                          className="w-full h-full object-cover"
                          unoptimized
                        />
                      ) : (
                        <div className="w-full h-full flex items-center justify-center">
                          <TrendingUp className="w-12 h-12 text-[#959595]" />
                        </div>
                      )}
                    </div>

                    {/* Bid Info */}
                    <div className="flex-1">
                      <div className="flex items-start justify-between mb-3">
                        <div>
                          <Link
                            href={`/imoveis/${bid.property_id}`}
                            className="text-xl font-bold text-[#E6C98B] hover:text-[#A8C97F] transition-colors"
                          >
                            {bid.properties?.title || "Propriedade"}
                          </Link>
                          <p className="text-[#A8C97F] text-sm mt-1">
                            {bid.properties?.location || "Localiza├º├úo n├úo dispon├¡vel"}
                          </p>
                        </div>

                        <div className={`flex items-center gap-2 px-4 py-2 rounded-full border-2 ${getStatusColor(bid.status)}`}>
                          {getStatusIcon(bid.status)}
                          <span className="font-semibold text-sm">{getStatusLabel(bid.status)}</span>
                        </div>
                      </div>

                      {/* Bid Details */}
                      <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mb-4">
                        <div>
                          <p className="text-[#676767] text-xs mb-1">Seu Lance</p>
                          <p className="text-[#B7791F] font-bold text-lg">
                            R$ {bid.bid_amount.toLocaleString("pt-BR")}
                          </p>
                        </div>

                        <div>
                          <p className="text-[#676767] text-xs mb-1">Lance Mais Alto</p>
                          <p className="text-[#E6C98B] font-bold text-lg">
                            R$ {bid.highest_bid?.toLocaleString("pt-BR") || "-"}
                          </p>
                          {bid.highest_bid && bid.highest_bid > bid.bid_amount && (
                            <p className="text-red-400 text-xs mt-1">­ƒöÑ Voc├¬ foi superado</p>
                          )}
                        </div>

                        <div>
                          <p className="text-[#676767] text-xs mb-1">Lances Concorrentes</p>
                          <p className="text-[#A8C97F] font-bold text-lg">
                            {bid.competing_bids || 0}
                          </p>
                        </div>

                        <div>
                          <p className="text-[#676767] text-xs mb-1">Data do Lance</p>
                          <p className="text-[#676767] text-sm">
                            {new Date(bid.created_at).toLocaleDateString("pt-BR")}
                          </p>
                        </div>
                      </div>

                      {/* Message */}
                      {bid.message && (
                        <div className="bg-[#2a2a1a] rounded-lg p-3 mb-4">
                          <p className="text-[#8B9B6E] text-sm">{bid.message}</p>
                        </div>
                      )}

                      {/* Actions */}
                      <div className="flex gap-3">
                        <Link
                          href={`/imoveis/${bid.property_id}`}
                          className="flex items-center gap-2 px-4 py-2 bg-gradient-to-r from-[#A8C97F] to-[#0D7377] text-white font-semibold rounded-lg hover:scale-105 transition-all"
                        >
                          <Eye className="w-4 h-4" />
                          Ver Propriedade
                        </Link>

                        {bid.status === "pending" && bid.highest_bid && bid.highest_bid > bid.bid_amount && (
                          <Link
                            href={`/imoveis/${bid.property_id}#bid`}
                            className="flex items-center gap-2 px-4 py-2 border-2 border-[#E6C98B] text-[#E6C98B] font-semibold rounded-lg hover:bg-[#E6C98B]/10 transition-all"
                          >
                            <DollarSign className="w-4 h-4" />
                            Aumentar Lance
                          </Link>
                        )}
                      </div>
                    </div>
                  </div>
                </div>
              </div>
            ))}
          </div>
        ) : (
          <div className="text-center py-20">
            <div className="w-32 h-32 mx-auto mb-6 bg-[#2a2a1a] rounded-full flex items-center justify-center">
              <TrendingUp className="w-16 h-16 text-[#676767]" />
            </div>
            <h2 className="text-2xl font-bold text-[#E6C98B] mb-3">
              Nenhum lance encontrado
            </h2>
            <p className="text-[#A8C97F] mb-6">
              {filter === "all"
                ? "Voc├¬ ainda n├úo fez nenhum lance em propriedades"
                : `Nenhum lance com status "${getStatusLabel(filter)}"`}
            </p>
            <Link
              href="/imoveis"
              className="inline-block px-6 py-3 bg-gradient-to-r from-[#A8C97F] to-[#0D7377] text-white font-bold rounded-full hover:scale-105 transition-all"
            >
              Explorar Propriedades
            </Link>
          </div>
        )}
      </div>
    </div>
  );
}

"use client";

import { useEffect, useState } from "react";
import { useRouter } from "next/navigation";
import { useAuth } from "@/components/AuthProvider";
import { createClientComponentClient } from "@supabase/auth-helpers-nextjs";
import { Trash2, Edit, Eye, EyeOff, PlusCircle, Home, Package } from "lucide-react";
import { useToast } from "@/components/ToastNotification";
import Image from "next/image";
import Link from "next/link";

interface Property {
  id: string;
  nome: string;
  preco: number;
  fotos: string[];
  localizacao: string;
  created_at: string;
}

interface Listing {
  id: string;
  title: string;
  price: number;
  photos: string[];
  city: string;
  state: string;
  created_at: string;
  is_featured: boolean;
}

export default function MeusAnunciosPage() {
  const { user, loading: authLoading } = useAuth();
  const router = useRouter();
  const { showToast } = useToast();
  const supabase = createClientComponentClient();

  const [loading, setLoading] = useState(true);
  const [properties, setProperties] = useState<Property[]>([]);
  const [listings, setListings] = useState<Listing[]>([]);
  const [activeTab, setActiveTab] = useState<"properties" | "listings">("properties");
  const [deleting, setDeleting] = useState<string | null>(null);

  useEffect(() => {
    if (!authLoading && !user) {
      router.push("/entrar?redirect=/meus-anuncios");
    }
  }, [user, authLoading, router]);

  useEffect(() => {
    if (user) {
      void loadUserData();
    }
  }, [user]);

  const loadUserData = async () => {
    if (!user) return;

    setLoading(true);
    try {
      // Load properties
      const { data: propsData, error: propsError } = await supabase
        .from("sitios")
        .select("*")
        .eq("user_id", user.id)
        .order("created_at", { ascending: false });

      if (propsError) throw propsError;
      setProperties(propsData || []);

      // Load AcheMeCoisas listings
      const { data: listingsData, error: listingsError } = await supabase
        .from("listings")
        .select("*")
        .eq("user_id", user.id)
        .order("created_at", { ascending: false });

      if (listingsError) throw listingsError;
      setListings(listingsData || []);
    } catch (error: any) {
      showToast({ 
        type: "error", 
        title: "Erro ao carregar an├║ncios",
        message: error.message 
      });
    } finally {
      setLoading(false);
    }
  };

  const handleDeleteProperty = async (id: string) => {
    if (!confirm("Tem certeza que deseja excluir esta propriedade?")) return;

    setDeleting(id);
    try {
      const { error } = await supabase.from("sitios").delete().eq("id", id);

      if (error) throw error;

      setProperties(properties.filter((p) => p.id !== id));
      showToast({ 
        type: "success", 
        title: "Propriedade exclu├¡da com sucesso!" 
      });
    } catch (error: any) {
      showToast({ 
        type: "error", 
        title: "Erro ao excluir propriedade",
        message: error.message 
      });
    } finally {
      setDeleting(null);
    }
  };

  const handleDeleteListing = async (id: string) => {
    if (!confirm("Tem certeza que deseja excluir este an├║ncio?")) return;

    setDeleting(id);
    try {
      const { error } = await supabase.from("listings").delete().eq("id", id);

      if (error) throw error;

      setListings(listings.filter((l) => l.id !== id));
      showToast({ 
        type: "success", 
        title: "An├║ncio exclu├¡do com sucesso!" 
      });
    } catch (error: any) {
      showToast({ 
        type: "error", 
        title: "Erro ao excluir an├║ncio",
        message: error.message 
      });
    } finally {
      setDeleting(null);
    }
  };

  if (authLoading || loading) {
    return (
      <div className="min-h-screen bg-[#0a0a0a] flex items-center justify-center">
        <div className="text-[#D4A574] text-xl">Carregando seus an├║ncios...</div>
      </div>
    );
  }

  if (!user) return null;

  return (
    <main className="min-h-screen bg-[#0a0a0a] pt-24 pb-16">
      <div className="max-w-7xl mx-auto px-4">
        {/* Header */}
        <div className="flex items-center justify-between mb-8">
