"use client";

import { useState, useEffect } from "react";

type ProposalFormProps = {
  propId?: string | null;
};

export default function ProposalForm({
  propId,
}: ProposalFormProps): JSX.Element {
  const [isAuthorized, setIsAuthorized] = useState(false);
  const [checkingAuth, setCheckingAuth] = useState(true);
  const [authCode, setAuthCode] = useState("");
  
  const [formData, setFormData] = useState({
    nome: "",
    email: "",
    telefone: "",
    documento: "",
    valor: "",
    condicoes: "",
    justificativa: "",
    mensagem: "",
  });
  
  const [status, setStatus] = useState<"idle" | "sending" | "sent" | "error">("idle");

  useEffect(() => {
    // Check if user has visited the property (authorization)
    const checkAuthorization = async () => {
      if (!propId) {
        setCheckingAuth(false);
        return;
      }

      try {
        const response = await fetch(`/api/check-authorization?propId=${propId}`);
        const data = await response.json();
        setIsAuthorized(data.authorized || false);
      } catch (error) {
        console.error("Erro ao verificar autoriza├º├úo:", error);
        setIsAuthorized(false);
      } finally {
        setCheckingAuth(false);
      }
    };

    void checkAuthorization();
  }, [propId]);

  const handleAuthCodeSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    
    try {
      const response = await fetch("/api/validate-auth-code", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ code: authCode, propId }),
      });

      const data = await response.json();
      
      if (data.valid) {
        setIsAuthorized(true);
        alert("C├│digo validado! Voc├¬ pode enviar sua proposta.");
      } else {
        alert("C├│digo inv├ílido. Por favor, verifique e tente novamente.");
