"use client";

import { useState } from "react";

interface ContactFormProps {
  itemTitle: string;
}

export default function ContactForm({ itemTitle }: ContactFormProps): JSX.Element {
  const [form, setForm] = useState({
    nome: "",
    email: "",
    telefone: "",
    mensagem: "",
  });

  const [status, setStatus] = useState<"idle" | "sending" | "sent" | "error">("idle");

  const handleSubmit = async (e: React.FormEvent<HTMLFormElement>): Promise<void> => {
    e.preventDefault();
    setStatus("sending");
    try {
      await new Promise((r) => setTimeout(r, 1000)); // simula envio
      setStatus("sent");
    } catch {
      setStatus("error");
    }
  };

  return (
    <section className="bg-white rounded-2xl shadow p-6">
      <h2 className="text-2xl font-semibold mb-4 text-gray-800">
        Contate o anunciante sobre &quot;{itemTitle}&quot;
      </h2>

      <form onSubmit={handleSubmit} className="space-y-4">
        <input
          type="text"
          placeholder="Seu nome completo"
          value={form.nome}
          onChange={(e) => setForm({ ...form, nome: e.target.value })}
          required
          className="w-full border rounded-lg p-3"
        />
        <input
          type="email"
          placeholder="Seu e-mail"
          value={form.email}
          onChange={(e) => setForm({ ...form, email: e.target.value })}
          required
          className="w-full border rounded-lg p-3"
        />
        <input
          type="tel"
          placeholder="Telefone ou WhatsApp"
          value={form.telefone}
          onChange={(e) => setForm({ ...form, telefone: e.target.value })}
          className="w-full border rounded-lg p-3"
        />
        <textarea
          placeholder="Escreva sua mensagem..."
          value={form.mensagem}
          onChange={(e) => setForm({ ...form, mensagem: e.target.value })}
          required
          className="w-full border rounded-lg p-3 min-h-[120px]"
        />

        <button
          type="submit"
          disabled={status === "sending"}
          className="bg-primary text-white px-6 py-3 rounded-lg font-medium hover:bg-green-800 transition"
        >
          {status === "sending" ? "Enviando..." : "Enviar mensagem"}
        </button>

        {status === "sent" && (
          <p className="text-green-600 font-medium mt-2">Mensagem enviada com sucesso!</p>
        )}
        {status === "error" && (
          <p className="text-red-600 font-medium mt-2">Erro ao enviar. Tente novamente.</p>
        )}
      </form>
    </section>
  );
}

"use client";

import { useEffect, useRef } from "react";

// Use global `window.google` declared in repo-level d.ts

type MapKmlViewerProps = {
  kmlUrl: string; // e.g. "/maps/carcara.kml"
  center?: any; // allow any to avoid global google type dependence during triage
  zoom?: number;
};

export default function MapKmlViewer({
  kmlUrl,
  center = { lat: -18.2795, lng: -48.8325 },
  zoom = 15,
}: MapKmlViewerProps) {
  const ref = useRef<HTMLDivElement | null>(null);

  useEffect(() => {
      let map: any = null;
      let kmlLayer: any = null;

    const init = async () => {
      const apiKey = process.env.NEXT_PUBLIC_GOOGLE_MAPS_API_KEY;
      if (!apiKey) {
        console.warn("Missing NEXT_PUBLIC_GOOGLE_MAPS_API_KEY");
      }
      // Load Google Maps script (one-time)
      if (!window.google?.maps) {
        await new Promise<void>((resolve, reject) => {
          const script = document.createElement("script");
          script.src = `https://maps.googleapis.com/maps/api/js?key=${apiKey}&v=weekly`;
          script.async = true;
          script.onload = () => resolve();
          script.onerror = () => reject(new Error("Failed to load Google Maps"));
          document.head.appendChild(script);
        });
      }
      if (!ref.current) return;

      map = new window.google.maps.Map(ref.current, {
        center,
        zoom,
        mapTypeId: "satellite",
        disableDefaultUI: false,
        styles: [
          { elementType: "geometry", stylers: [{ color: "#0b0b0b" }] },
          { elementType: "labels.text.fill", stylers: [{ color: "#bfa97a" }] },
          { elementType: "labels.text.stroke", stylers: [{ color: "#0b0b0b" }] },
        ],
      });

      kmlLayer = new window.google.maps.KmlLayer({
        url: `${location.origin}${kmlUrl}`,
        map,
        preserveViewport: false,
        suppressInfoWindows: false,
      });

      kmlLayer.addListener("status_changed", () => {
        const status = kmlLayer?.getStatus();
        if (status !== "OK") console.warn("KML status:", status);
      });
    };

    void init();
    return () => {
      // Maps API cleans itself when element is removed; just null refs
      map = null;
      kmlLayer = null;
    };
  }, [kmlUrl, center, zoom]);

  return <div ref={ref} className="w-full h-[420px] rounded-xl border border-[#242424]" />;
}

