        <p className="mt-1 text-sm text-red-600">{error}</p>
      )}
    </div>
  );
}

'use client';

import { useState } from 'react';

interface PersonalInfoStepProps {
  initialData: Partial<{
    full_name: string;
    cpf: string;
    date_of_birth: string;
    phone_number: string;
  }>;
  onSubmit: (data: any) => void;
  loading: boolean;
}

export default function PersonalInfoStep({
  initialData,
  onSubmit,
  loading,
}: PersonalInfoStepProps) {
  const [formData, setFormData] = useState({
    full_name: initialData.full_name || '',
    cpf: initialData.cpf || '',
    date_of_birth: initialData.date_of_birth || '',
    phone_number: initialData.phone_number || '',
  });

  const [errors, setErrors] = useState<Record<string, string>>({});

  const formatCPF = (value: string) => {
    const numbers = value.replace(/\D/g, '');
    if (numbers.length <= 11) {
      return numbers
        .replace(/(\d{3})(\d)/, '$1.$2')
        .replace(/(\d{3})(\d)/, '$1.$2')
        .replace(/(\d{3})(\d{1,2})$/, '$1-$2');
    }
    return value;
  };

  const formatPhone = (value: string) => {
    const numbers = value.replace(/\D/g, '');
    if (numbers.length <= 11) {
      return numbers
        .replace(/(\d{2})(\d)/, '($1) $2')
        .replace(/(\d{5})(\d)/, '$1-$2');
    }
    return value;
  };

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    let { name, value } = e.target;

    if (name === 'cpf') {
      value = formatCPF(value);
    } else if (name === 'phone_number') {
      value = formatPhone(value);
    }

    setFormData({ ...formData, [name]: value });
    
    // Clear error when user starts typing
    if (errors[name]) {
      setErrors({ ...errors, [name]: '' });
    }
  };

  const validate = () => {
    const newErrors: Record<string, string> = {};

    if (!formData.full_name.trim()) {
      newErrors.full_name = 'Nome completo ├® obrigat├│rio';
    }

    const cpfNumbers = formData.cpf.replace(/\D/g, '');
    if (!cpfNumbers) {
      newErrors.cpf = 'CPF ├® obrigat├│rio';
    } else if (cpfNumbers.length !== 11) {
      newErrors.cpf = 'CPF inv├ílido (deve ter 11 d├¡gitos)';
    }

    if (!formData.date_of_birth) {
      newErrors.date_of_birth = 'Data de nascimento ├® obrigat├│ria';
    } else {
      const birthDate = new Date(formData.date_of_birth);
      const today = new Date();
      const age = today.getFullYear() - birthDate.getFullYear();
      if (age < 18) {
        newErrors.date_of_birth = 'Voc├¬ deve ter pelo menos 18 anos';
      }
    }

    if (formData.phone_number) {
      const phoneNumbers = formData.phone_number.replace(/\D/g, '');
      if (phoneNumbers.length < 10) {
        newErrors.phone_number = 'Telefone inv├ílido';
      }
    }

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (validate()) {
      onSubmit(formData);
    }
  };

  return (
    <div>
      <h2 className="text-2xl font-bold text-gray-900 mb-2">
        Informa├º├Áes Pessoais
      </h2>
      <p className="text-gray-600 mb-6">
        Para garantir a seguran├ºa da plataforma, precisamos verificar sua identidade.
      </p>

      <form onSubmit={handleSubmit} className="space-y-6">
        {/* Full Name */}
        <div>
          <label htmlFor="full_name" className="block text-sm font-medium text-gray-700 mb-2">
            Nome Completo *
          </label>
          <input
            type="text"
            id="full_name"
            name="full_name"
