'use client';

import { useState } from 'react';
import { supabase } from '@/lib/supabaseClient';
import { X } from 'lucide-react';

interface AccountModalProps {
  open: boolean;
  onClose: () => void;
}

export default function AccountModal({ open, onClose }: AccountModalProps) {
  const [mode, setMode] = useState<'login' | 'register' | 'phone'>('login');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [fullName, setFullName] = useState('');
  const [phone, setPhone] = useState('');
  const [otp, setOtp] = useState('');
  const [otpSent, setOtpSent] = useState(false);

  const signInWithProvider = async (provider: 'google') => {
    setLoading(true);
    setError('');
    
    try {
      // Get the current URL origin
      const origin = typeof window !== 'undefined' ? window.location.origin : '';
      const redirectUrl = `${origin}/api/auth/callback`;
      
      const { data: _data, error } = await supabase.auth.signInWithOAuth({
        provider,
        options: {
          redirectTo: redirectUrl,
          queryParams: {
            access_type: 'offline',
            prompt: 'consent',
          },
        },
      });
      
      if (error) {
        console.error('OAuth error:', error);
        throw error;
      }
      
      // The modal will close automatically when auth state changes
    } catch (err: unknown) {
      console.error('Sign in error:', err);
      const msg = ((): string => {
        if (typeof err === 'string') return err;
        if (err && typeof err === 'object' && 'message' in err) {
          const m = (err as Record<string, unknown>)['message'];
          if (typeof m === 'string') return m;
        }
        return 'Failed to sign in. Please try again.';
      })();
      setError(msg);
    } finally {
      setLoading(false);
    }
  };

  const handleEmailSignIn = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError('');

    try {
      const { error } = await supabase.auth.signInWithPassword({
        email,
        password,
      });

      if (error) throw error;
      onClose();
    } catch (err: unknown) {
      const m = (err && typeof err === 'object' && 'message' in err) ? (err as Record<string, unknown>)['message'] : undefined;
      setError(typeof m === 'string' ? m : 'Erro ao entrar.');
    } finally {
      setLoading(false);
    }
  };

  const handleEmailSignUp = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError('');

    try {
      const { error } = await supabase.auth.signUp({
        email,
        password,
        options: {
          data: {
            full_name: fullName,
            phone: phone,
          },
        },
      });

      if (error) throw error;
      setError('Check your email to confirm your account!');
      setTimeout(() => {
        onClose();
      }, 3000);
    } catch (err: unknown) {
      const m = (err && typeof err === 'object' && 'message' in err) ? (err as Record<string, unknown>)['message'] : undefined;
      setError(typeof m === 'string' ? m : 'Erro ao criar conta.');
    } finally {
      setLoading(false);
    }
  };

  const handlePhoneSignIn = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError('');

    try {
      if (!otpSent) {
        // Send OTP
        const { error } = await supabase.auth.signInWithOtp({
          phone: phone.startsWith('+') ? phone : `+55${phone.replace(/\D/g, '')}`,
        });
        
        if (error) throw error;
        setOtpSent(true);
        setError('C├│digo enviado! Verifique seu WhatsApp/SMS.');
      } else {
        // Verify OTP
        const { error } = await supabase.auth.verifyOtp({
          phone: phone.startsWith('+') ? phone : `+55${phone.replace(/\D/g, '')}`,
          token: otp,
          type: 'sms',
        });
        
        if (error) throw error;
        onClose();
      }
    } catch (err: unknown) {
      const m = (err && typeof err === 'object' && 'message' in err) ? (err as Record<string, unknown>)['message'] : undefined;
      setError(typeof m === 'string' ? m : 'Erro ao processar c├│digo.');
      setOtpSent(false);
    } finally {
      setLoading(false);
    }
  };

  if (!open) return null;

  return (
    <div className="fixed inset-0 bg-black/70 backdrop-blur-sm flex items-center justify-center z-50 p-4">
      <div className="bg-gradient-to-br from-[#1a1a1a] to-[#0d0d0d] border-2 border-[#2a2a1a] rounded-2xl w-full max-w-md relative shadow-2xl">
        {/* Close Button */}
        <button
          onClick={onClose}
          className="absolute top-4 right-4 text-[#676767] hover:text-[#A8C97F] transition-colors"
          aria-label="Close"
        >
          <X className="w-6 h-6" />
        </button>

        <div className="p-8">
          <h2 className="text-3xl font-bold text-transparent bg-clip-text bg-gradient-to-r from-[#E6C98B] to-[#A8C97F] mb-2">
            {mode === 'login' ? 'Entrar' : mode === 'register' ? 'Cadastrar' : 'Login com Telefone'}
