import CANONICAL_PROPERS from '@/lib/AcheMeRuralPropers.json';
import { fetchCanonicalSitios, mapCanonicalPropersToSitios } from '@/lib/carcaraHelpers';
import { PropertyCard } from '@publimicro/ui';

type Sitio = any;

export default function CarcaraHighlights({ limit = 6, hideTestListings = true }: { limit?: number; hideTestListings?: boolean }) {
  const [sitios, setSitios] = useState<Sitio[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    // Static immediate mapping
    try {
      const staticMapped = mapCanonicalPropersToSitios(CANONICAL_PROPERS).slice(0, limit);
      setSitios(staticMapped as Sitio[]);
    } catch (err) {
      console.warn('CarcaraHighlights: failed to map static canonical propers', err);
      setSitios([]);
    }

    // Attempt live refresh
    void (async () => {
      try {
        const live = await fetchCanonicalSitios({ limit, hideTestListings });
        if (live && live.length > 0) setSitios(live as Sitio[]);
      } catch (err) {
        console.warn('CarcaraHighlights: live fetch failed', err);
      } finally {
        setLoading(false);
      }
    })();
  }, [limit, hideTestListings]);

  const brl = (v: number | null | undefined) => {
    try {
      if (!v && v !== 0) return undefined;
      return new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(v as number);
    } catch (_e) {
      return undefined;
    }
  };

  return (
    <section className="py-16">
      <h2 className="text-4xl font-bold text-[#E6C98B] mb-8 text-center">S├¡tios Dispon├¡veis - Lances Abertos</h2>
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {loading ? (
          // Simple placeholders while loading
          Array.from({ length: limit }).map((_, i) => (
            <div key={i} className="h-80 bg-gradient-to-br from-[#1a1a1a] to-[#0d0d0d] rounded-xl animate-pulse" />
          ))
        ) : (
          sitios.map((s: any) => {
            const opening = s.openingOffer || s.lance_inicial || s.preco || null;
            const estimated = s.estimatedMarketValue || null;
            const locationText = `${s.zona || 'Zona Rural'} - ${s.localizacao || s.location || 'Corumba├¡ba/GO'}`;
            const tagline = s.tagline ? `${s.tagline} ÔÇö ` : '';
            const desc = `${tagline}${locationText}\nEstimated: ${estimated ? brl(estimated) : 'ÔÇö'} | Opening: ${opening ? brl(opening) : 'ÔÇö'}`;

            return (
              <PropertyCard
                key={s.id}
                id={s.id}
                title={s.nome || s.title}
                description={desc}
                price={opening || 0}
                currentBid={s.current_bid}
                featured={s.destaque}
                location={{ city: s.localizacao || 'Corumba├¡ba', state: 'GO', neighborhood: s.zona }}
                area={{ total: s.tamanho || s.area_total || s.total_area || 0 }}
                photos={s.fotos || []}
                link={`/imoveis/${s.id}`}
                type="sitio"
              />
            );
          })
        )}
      </div>
    </section>
  );
}

"use client";

import { useState, useEffect } from 'react';
import { Heart } from 'lucide-react';
import { supabase } from '@/lib/supabaseClient';

interface FavoritesButtonProps {
  propertyId: string;
  userId?: string | null;
  size?: 'sm' | 'md' | 'lg';
}

export default function FavoritesButton({ propertyId, userId, size = 'md' }: FavoritesButtonProps) {
  const [isFavorite, setIsFavorite] = useState(false);
  const [loading, setLoading] = useState(false);

  const sizeClasses = {
    sm: 'w-8 h-8',
    md: 'w-10 h-10',
    lg: 'w-12 h-12'
  };

  const iconSizes = {
    sm: 'w-4 h-4',
    md: 'w-5 h-5',
    lg: 'w-6 h-6'
  };

  useEffect(() => {
    if (!userId) return;

    async function checkFavorite() {
      const { data } = await supabase
        .from('property_favorites')
        .select('id')
        .eq('property_id', propertyId)
        .eq('user_id', userId)
        .single();
      
      setIsFavorite(!!data);
    }

    void checkFavorite();
  }, [propertyId, userId]);

  const handleToggleFavorite = async (e: React.MouseEvent) => {
    e.preventDefault();
    e.stopPropagation();

    if (!userId) {
      alert('Voc├¬ precisa fazer login para adicionar favoritos!');
      window.location.href = '/entrar';
      return;
    }

    setLoading(true);
    try {
      if (isFavorite) {
        await supabase
          .from('property_favorites')
          .delete()
          .eq('property_id', propertyId)
          .eq('user_id', userId);
        setIsFavorite(false);
      } else {
        await supabase
          .from('property_favorites')
          .insert({ property_id: propertyId, user_id: userId });
        setIsFavorite(true);
      }
    } catch (error) {
      console.error('Error toggling favorite:', error);
    } finally {
      setLoading(false);
    }
  };

  return (
    <button
      onClick={handleToggleFavorite}
      disabled={loading}
      className={`${sizeClasses[size]} rounded-full flex items-center justify-center transition-all ${
        isFavorite
          ? 'bg-[#A8C97F] text-[#0a0a0a] hover:bg-[#B7791F]'
          : 'bg-[#0a0a0a]/80 text-[#D4A574] hover:bg-[#A8C97F]/20 border-2 border-[#2a2a1a]'
      } ${loading ? 'opacity-50 cursor-wait' : 'hover:scale-110'}`}
      aria-label={isFavorite ? 'Remover dos favoritos' : 'Adicionar aos favoritos'}
      title={isFavorite ? 'Remover dos favoritos' : 'Adicionar aos favoritos'}
    >
      <Heart
        className={iconSizes[size]}
        fill={isFavorite ? 'currentColor' : 'none'}
        strokeWidth={2}
      />
    </button>
  );
}

