              </div>
              <h3 className="text-2xl font-bold text-[#E6C98B] mb-3">Login Necess├írio</h3>
              <p className="text-[#676767] mb-6">
                Para agendar uma visita, voc├¬ precisa estar logado.
              </p>
              <button
                onClick={() => router.push(`/entrar?redirect=${encodeURIComponent(window.location.pathname)}`)}
