                      form.visit_type === 'in_person'
                        ? 'border-[#0D7377] bg-[#0D7377]/20 text-[#0D7377]'
                        : 'border-[#3a3a2a] bg-[#2a2a2a] text-[#676767] hover:border-[#4a4a3a]'
