              <div>
                <label className="block text-sm font-medium text-[#B7791F] mb-2">
                  Data e Hora Preferencial *
                </label>
                <input
                  type="datetime-local"
                  name="scheduled_at"
                  value={form.scheduled_at}
                  onChange={handleChange}
                  min={new Date().toISOString().slice(0, 16)}
