                )}
              </button>
            </form>
          )}
        </div>
      </div>
      </FocusLock>
    </div>
  );
}

"use client";

import { useState, useEffect, useRef } from "react";
import { X, Home, Search, Map, TrendingUp, Heart, CheckCircle } from "lucide-react";
import Link from "next/link";
import FocusLock from "react-focus-lock";

export default function WelcomeModal() {
  const [isOpen, setIsOpen] = useState(false);
  const [currentStep, setCurrentStep] = useState(0);
  const previouslyFocusedElement = useRef<HTMLElement | null>(null);

  useEffect(() => {
    // Check if user has seen the welcome modal
    const hasSeenWelcome = localStorage.getItem("hasSeenWelcome");
    
    if (!hasSeenWelcome) {
      // Store currently focused element
      previouslyFocusedElement.current = document.activeElement as HTMLElement;
      // Show modal after 1 second delay
      setTimeout(() => setIsOpen(true), 1000);
    }
  }, []);

  // Handle Escape key
  useEffect(() => {
    const handleEscape = (e: KeyboardEvent) => {
      if (e.key === "Escape" && isOpen) {
        handleClose();
      }
    };

    if (isOpen) {
      document.addEventListener("keydown", handleEscape);
    }

    return () => {
      document.removeEventListener("keydown", handleEscape);
    };
  }, [isOpen]);

  const handleClose = () => {
    setIsOpen(false);
    localStorage.setItem("hasSeenWelcome", "true");
    
    // Return focus to previously focused element
    if (previouslyFocusedElement.current) {
      previouslyFocusedElement.current.focus();
    }
  };

  const handleNext = () => {
    if (currentStep < steps.length - 1) {
      setCurrentStep(currentStep + 1);
    } else {
      handleClose();
    }
  };

  const handlePrevious = () => {
    if (currentStep > 0) {
      setCurrentStep(currentStep - 1);
    }
  };

  const steps = [
    {
      icon: <Home className="w-16 h-16 text-[#A8C97F]" />,
      title: "Bem-vindo ao PubliMicro! ­ƒÄë",
      description: "Sua plataforma completa para encontrar e negociar propriedades rurais e urbanas. Vamos fazer um tour r├ípido?",
      highlight: "Marketplace confi├ível desde 2024"
    },
    {
      icon: <Search className="w-16 h-16 text-[#D4A574]" />,
      title: "Busca Inteligente",
      description: "Use nossa busca avan├ºada com filtros de pre├ºo, ├írea, localiza├º├úo e muito mais. Encontre exatamente o que procura.",
      highlight: "Resultados instant├óneos com autocomplete"
    },
    {
      icon: <Map className="w-16 h-16 text-[#8B9B6E]" />,
      title: "Explore por Categoria",
      description: "Navegue por PubliProper (im├│veis), PubliMotors (ve├¡culos), PubliMachina (m├íquinas) e muito mais.",
      highlight: "8 categorias especializadas"
    },
    {
      icon: <TrendingUp className="w-16 h-16 text-[#6A1B9A]" />,
