type FetchOptions = {
  limit?: number;
  hideTestListings?: boolean;
};

const isTestTitle = (t?: string) => {
  if (!t) return false;
  return /\b(test|demo|dummy|lorem|sample)\b/i.test(t);
};

/**
 * Fetch the canonical Carcar├í sitios. Tries to fetch by projeto='S├¡tios Carcar├í'
 * then falls back to the canonical id list. Also attaches the current highest bid.
 */
export async function fetchCanonicalSitios(opts: FetchOptions = {}) {
  const { limit = 6, hideTestListings = true } = opts;
  try {
    // Try project-based query first
    let { data, error } = await supabase
      .from('properties')
      .select('*')
      .eq('projeto', 'S├¡tios Carcar├í')
      .order('price', { ascending: true })
      .limit(limit);

    if (error) {
      console.warn('fetchCanonicalSitios: projeto query error', error);
    }

    // If no rows returned, fallback to canonical id list
    if (!data || data.length === 0) {
      const { data: fbData, error: fbErr } = await supabase
        .from('properties')
        .select('*')
        .in('id', CANONICAL_CARCARA_IDS)
        .order('price', { ascending: true });

      if (fbErr) {
        console.warn('fetchCanonicalSitios: fallback query error', fbErr);
      }
      data = fbData || [];
    }

    // Attach current highest bid for each property
    const sitiosWithBids = await Promise.all(
      (data || []).map(async (sitio: any) => {
        const { data: bids } = await supabase
          .from('proposals')
          .select('amount')
          .eq('property_id', sitio.id)
          .order('amount', { ascending: false })
          .limit(1);

        return {
          ...sitio,
          current_bid: bids && bids.length > 0 ? bids[0].amount : null,
        };
      })
    );

    // Optional filtering for obvious test/demo titles
    const filtered = hideTestListings
      ? (sitiosWithBids as any[]).filter((s) => !isTestTitle(s.nome || s.title))
      : sitiosWithBids;

    return filtered;
  } catch (err) {
    console.error('fetchCanonicalSitios unexpected error', err);
    return [];
  }
}

/**
 * Map the canonical JSON entries (from `AcheMeRuralPropers.json`) to the
 * Sitio shape the UI expects. Accepts an array of canonical records so the
 * caller controls the source (keeps helper pure and testable).
 */
export function mapCanonicalPropersToSitios(canonical: Array<any>) {
  if (!Array.isArray(canonical)) return [];
  return canonical.map((p) => ({
    id: p.slug,
    slug: p.slug,
    title: p.title,
    nome: p.title,
    location: `${p.latitude},${p.longitude}`,
    localizacao: p.short || `${p.latitude},${p.longitude}`,
    fotos: p.fotos || [],
    kml_url: p.kml_url,
    short: p.short,
    total_area: p.total_area || null,
    current_bid: null,
    tagline: p.tagline || null,
    estimatedMarketValue: p.estimatedMarketValue || null,
    openingOffer: p.openingOffer || null,
    moodboard: p.moodboard || null,
    purpose: p.purpose || null,
  }));
}

// Comparison helper functions
export function addToComparison(propertyId: string): boolean {
  try {
    const stored = localStorage.getItem('comparison');
    const ids: string[] = stored ? JSON.parse(stored) : [];
    
    if (ids.includes(propertyId)) {
      return false; // Already in comparison
    }
    
    if (ids.length >= 3) {
      alert('Voc├¬ pode comparar no m├íximo 3 propriedades por vez.');
      return false;
    }
    
    ids.push(propertyId);
    localStorage.setItem('comparison', JSON.stringify(ids));
    return true;
  } catch (error) {
    console.error('Error adding to comparison:', error);
    return false;
  }
}

export function removeFromComparison(propertyId: string): {
  try {
    const stored = localStorage.getItem('comparison');
    const ids: string[] = stored ? JSON.parse(stored) : [];
    const filtered = ids.filter(id => id !== propertyId);
    localStorage.setItem('comparison', JSON.stringify(filtered));
  } catch (error) {
    console.error('Error removing from comparison:', error);
  }
}

export function getComparisonIds(): string[] {
  try {
    const stored = localStorage.getItem('comparison');
    return stored ? JSON.parse(stored) : [];
  } catch (error) {
    console.error('Error getting comparison IDs:', error);
    return [];
  }
}

export function clearComparison(): {
  localStorage.removeItem('comparison');
}

export function getComparisonUrl(): string {
  const ids = getComparisonIds();
  if (ids.length === 0) return '/comparar';
  return `/comparar?ids=${ids.join(',')}`;
}

export function isInComparison(propertyId: string): boolean {
  const ids = getComparisonIds();
  return ids.includes(propertyId);
}

import { createServerClient } from '@supabase/ssr'
import { cookies } from 'next/headers'

// Minimal CookieStore interface used by the Supabase SSR helper
interface CookieStore {
  get(name: string): { value: string } | undefined;
  set(cookie: { name: string; value: string } & Record<string, any>): void;
}

export function createServerSupabaseClient() {
  // cookies() typing may differ across Next versions; narrow to a small interface instead of `any`
  const cookieStore = cookies() as unknown as CookieStore;
  
  return createServerClient(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!,
    {
      cookies: {
        get(name: string) {
          return cookieStore.get(name)?.value
        },
        set(name: string, value: string, options: Record<string, any>) {
          try {
            cookieStore.set({ name, value, ...options })
          } catch (_error) {
            // Can happen in Server Components
          }
        },
        remove(name: string, options: Record<string, any>) {
          try {
            cookieStore.set({ name, value: '', ...options })
          } catch (_error) {
            // Can happen in Server Components
          }
        },
      },
    }
  )
}

// Service role client for admin operations (server-only!)
export function createServiceSupabaseClient() {
  const url = process.env.NEXT_PUBLIC_SUPABASE_URL;
  const key = process.env.SUPABASE_SERVICE_ROLE_KEY;

  if (!url) {
    throw new Error('Missing NEXT_PUBLIC_SUPABASE_URL environment variable');
  }

  if (!key) {
    throw new Error('Missing SUPABASE_SERVICE_ROLE_KEY environment variable ÔÇö service client requires this key at runtime.');
  }

  return createServerClient(
    url,
    key,
    {
      cookies: {
        get() { return undefined },
        set() {},
        remove() {},
      },
    }
  )
}

import { createApi } from 'unsplash-js';

// Initialize Unsplash API with fallback
const accessKey = process.env.NEXT_PUBLIC_UNSPLASH_ACCESS_KEY || '';
const unsplash = accessKey ? createApi({ accessKey }) : null;

// Category-specific search queries for optimal image results
export const CATEGORY_QUERIES = {
  motors: 'luxury cars sports vehicles automobile',
  marine: 'boats yachts sailing ocean water',
  machina: 'heavy machinery equipment industrial construction',
  proper: 'modern architecture houses real estate buildings',
  share: 'collaboration teamwork community sharing',
  journey: 'travel wanderlust destinations landscape adventure',
  global: 'world globe international business skyline',
  tudo: 'marketplace shopping colorful products variety',
} as const;

export type CategoryKey = keyof typeof CATEGORY_QUERIES;

// Fallback images from Unsplash (direct URLs that don't require API key)
const FALLBACK_IMAGES: Record<CategoryKey, string> = {
  motors: 'https://images.unsplash.com/photo-1492144534655-ae79c964c9d7?w=800&q=80',
  marine: 'https://images.unsplash.com/photo-1540946485063-a40da27545f8?w=800&q=80',
  machina: 'https://images.unsplash.com/photo-1581092918056-0c4c3acd3789?w=800&q=80',
  proper: 'https://images.unsplash.com/photo-1580587771525-78b9dba3b914?w=800&q=80',
  share: 'https://images.unsplash.com/photo-1521737604893-d14cc237f11d?w=800&q=80',
  journey: 'https://images.unsplash.com/photo-1488646953014-85cb44e25828?w=800&q=80',
  global: 'https://images.unsplash.com/photo-1526778548025-fa2f459cd5c1?w=800&q=80',
  tudo: 'https://images.unsplash.com/photo-1441986300917-64674bd600d8?w=800&q=80',
};

/**
 * Fetch a random landscape image from Unsplash for a specific category
 * @param category - The category key (motors, marine, etc.)
 * @returns Image URL or fallback image if API unavailable
 */
export async function getRandomCategoryImage(category: CategoryKey): Promise<string | null> {
  // If no API key, return fallback immediately
  if (!unsplash) {
    console.log(`Using fallback image for ${category} (no API key configured)`);
    return FALLBACK_IMAGES[category];
  }

  try {
    const query = CATEGORY_QUERIES[category];
    
    const result = await unsplash.photos.getRandom({
      query,
      orientation: 'landscape',
      count: 1,
    });

    if (result.type === 'success' && result.response) {
      const photo = Array.isArray(result.response) ? result.response[0] : result.response;
      return photo.urls.regular;
    }

    // If API call fails, return fallback
    console.log(`Using fallback image for ${category} (API call failed)`);
    return FALLBACK_IMAGES[category];
  } catch (error) {
    console.error(`Error fetching Unsplash image for ${category}:`, error);
    return FALLBACK_IMAGES[category];
  }
}

/**
 * Fetch multiple random images for all categories at once
 * Useful for preloading section images
 */
export async function getAllCategoryImages(): Promise<Record<CategoryKey, string | null>> {
  const categories = Object.keys(CATEGORY_QUERIES) as CategoryKey[];
  
  const imagePromises = categories.map(async (category) => ({
    category,
    url: await getRandomCategoryImage(category),
  }));

  const results = await Promise.all(imagePromises);
  
  return results.reduce((acc, { category, url }) => {
    acc[category] = url;
    return acc;
  }, {} as Record<CategoryKey, string | null>);
}

/**
 * Track Unsplash download (required by API guidelines)
 * Call this when an image is actually displayed to the user
 */
export async function trackDownload(downloadLocation: string): Promise<void> {
  try {
    // The download location is provided in the photo response
    if (downloadLocation) {
      await fetch(downloadLocation);
    }
  } catch (error) {
    console.error('Error tracking Unsplash download:', error);
  }
}
